import type { TopicVerse } from './topicVerses';

// Verses of the Phaladīpikā of Mantreśvara that the topic yogas read from (the rules with `text: 'phala'`): chapters 10 (the 7th house) and the later house chapters. The Sanskrit is the text layer of the
// edition (`phaldipika_202310`, a scan of the print) with the plain misreadings corrected; the glosses are short summaries written for the app from the Sanskrit and the Hindi commentary, and the verse decides.
export const PHALA_VERSES: Record<number, TopicVerse[]> = {
  10: [
    { chapter: 10, verse: 1, sanskrit: ["शुभाधिपयुतेक्षिते सुतकलत्रभे लग्नतो", "विधोरपि तयोः शुभं त्वितरथा न सिद्धिस्तयोः ।", "सिताद्व्ययसुखाष्टगैः खरखगैरसन्मध्यगे", "सितेऽप्यथ शुभेतरेक्षितयुते च जायावधः ॥१॥"], gloss: "The 5th and 7th from the lagna, and from the Moon, joined or seen by a benefic or by their lords: good; otherwise not. Malefics in the 12th, 4th and 8th from Venus, Venus between malefics, or Venus joined or seen by malefics: the death of the wife.", note: "The word for \"from Venus\" in the second line was restored from the commentary." },
    { chapter: 10, verse: 2, sanskrit: ["दारेशे सुतगे प्रणष्टवनितोऽपुत्रोऽथवा धीश्वरो", "द्यूने वा निधनेश्वरोऽपि कुरुते पत्नीविनाशं ध्रुवम् ।", "क्षीणेन्दौ सुतगे व्ययास्ततनुगैः पापैरदारात्मजः", "स्त्रीसङ्गाद्धननाशनं मदगयोः स्वर्भानुभान्वोर्वदेत् ॥२॥"], gloss: "The 7th lord in the 5th: the wife is lost, and he is childless; the 5th lord or the 8th lord in the 7th: the death of the wife. A waning Moon in the 5th and malefics in the 12th, 7th and lagna: without wife and sons. The Sun and Rāhu in the 7th: loss of wealth through women." },
    { chapter: 10, verse: 3, sanskrit: ["शुक्रे वृश्चिकगे मदे मृतवधूः कामे वृषस्थे बुधे", "स्त्रीनाशस्त्वथ नीचगे सुरगुरौ द्यूनाधिरूढे तथा ।", "जामित्रे झषगे शनौ सति तथा भौमेऽथवा स्त्रीमृति-", "श्चन्द्रक्षेत्रगयोर्मदेऽर्कजकुजयोः पत्नी सती शोभना ॥३॥"], gloss: "Venus in Scorpio, Mercury in Taurus, Jupiter in its fall, or Saturn or Mars in Pisces in the 7th: the wife dies. Mars and Saturn together in Cancer in the 7th: the wife is virtuous and fair.", note: "Some letters of the last line were misread in the scan and are corrected from the commentary." },
    { chapter: 10, verse: 4, sanskrit: ["अस्ते वास्तपतावसद्ग्रहयुते दृष्टेऽप्यसन्मध्यगे", "नीचारातिगृहेऽर्ककान्त्यभिहते ब्रूयात्कलत्रच्युतिम् ।", "कामे वा सुतभाग्ययोर्विकलदारोऽसौ सपापे भृगौ", "शुक्रे वा कुजमन्दवर्गसहिते दृष्टे परस्त्रीरतः ॥४॥"], gloss: "The 7th or its lord joined or seen by malefics, between malefics, in its fall or an enemy sign, or combust: loss of the wife. Venus with malefics in the 7th, 5th or 9th: a sickly wife. Venus in a varga of Mars or Saturn and seen by them: fond of other men's wives." },
    { chapter: 10, verse: 5, sanskrit: ["भौमार्क्यस्ते भृगुजशशिनोर्दारहीनोऽसुतो वा", "क्लीबेऽस्ते वा भवति भवगौ द्वौ ग्रहौ स्त्रीद्वयं स्यात् ।", "द्विस्वभावक्षशे मदपतिसितौ तस्य जायाद्वयं स्यात्", "ताभ्यां युक्तैर्गगननिलयैर्दारसंख्यां वदन्तु ॥५॥"], gloss: "Mars and Saturn in the 7th from Venus and from the Moon: without a wife or sons. A neuter graha in the 7th and two grahas in the 11th, or the 7th lord with Venus in a dual sign or its navāṁśa: two wives. As many wives as the grahas joined to them.", note: "Some letters of the third line could not be read in the scan." },
    { chapter: 10, verse: 6, sanskrit: ["द्यूनेशे सबले शुभे सति वधूः साध्वी सुपुत्रान्विता", "…", "पापोऽपि स्वगृहं गतः शुभकरः पत्याश्च कामस्थिता", "हित्वा षड्व्ययरन्ध्रपान्मदनगाः सौम्यास्तु सौख्यावहाः ॥६॥"], gloss: "The 7th lord a strong benefic: a virtuous wife with good sons. A malefic 7th lord in its own sign in the 7th is good too. Benefics in the 7th give happiness, except the lords of the 6th, 12th and 8th.", note: "One line of the verse could not be read in the scan." },
    { chapter: 10, verse: 7, sanskrit: ["भार्यानाशस्त्वशुभसहितौ वीक्षितौ वार्थकामौ", "तत्र प्राहुस्त्वशुभफलदां क्रूरदृष्टिं विशेषात् ।", "एवं पत्न्या अपि सति मदे चाष्टमे वास्ति दोषः", "सौम्यैरदृष्टे सति शुभयुते दम्पती भाग्यवन्तौ ॥७॥"], gloss: "The 2nd and 7th joined or seen by malefics: the wife dies; in a woman's chart the 7th and 8th: the husband. Seen by benefics or joined to them: both are fortunate." },
    { chapter: 10, verse: 8, sanskrit: ["चन्द्रे समन्दे मदगे पुनर्भूः पतिर्भवेद्वाऽप्यसुतो विदारः ।", "नीचारिभस्थैरशुभैर्मदे स्त्रीपुंसोर्मृतिः स्यान्निधने धने वा ॥८॥"], gloss: "The Moon with Saturn in the 7th: a woman remarries; a man is without wife and sons. Malefics in the 7th, 8th or 2nd in their fall or an enemy sign: the death of the wife (of the husband in a woman's chart)." },
    { chapter: 10, verse: 9, sanskrit: ["लग्नात्कलत्रभवने समराशिसंज्ञे", "भावाधिपेऽपि च तथैव गतेऽसुरेज्ये ।", "सूर्याभितप्तरहिते सुतदारनाथे", "वीर्यान्विते तु जननं ससुतं कलत्रम् ॥९॥"], gloss: "The 7th an even sign, the 7th lord and Venus in even signs, the 5th and 7th lords strong and not combust: a good wife and sons." },
    { chapter: 10, verse: 10, sanskrit: ["कुटुम्बदारव्ययराशिनाथा जीवेक्षिताः कोणचतुष्टयस्थाः ।", "दारेश्वराद्वित्तकलत्रलाभे सौम्याः कलत्रं ससुतं सुखाढ्यम् ॥१०॥"], gloss: "The lords of the 2nd, 7th and 12th in a trikoṇa or kendra and seen by Jupiter, or benefics in the 2nd, 12th and 7th from the 7th lord: a happy wife with sons." },
    { chapter: 10, verse: 11, sanskrit: ["लग्नास्तनाथस्थितभांशकोणे नीचोच्चभे स्त्रीजननं च पत्युः ।", "चन्द्राष्टवर्गेऽधिकबिन्दुराशौ कलत्रजन्मेति तथा धवस्य ॥११॥"], gloss: "The birth sign of the wife: the 5th or 9th from the sign or navāṁśa of the lagna lord and the 7th lord, or their exaltation or fall sign, or the sign with most bindus in the Moon's aṣṭakavarga." },
    { chapter: 10, verse: 12, sanskrit: ["कामस्थकामाधिपभार्गवानामृक्षं दिशं शंसति तस्य पत्न्याः ।", "शुक्रोऽस्तपो वा तनुनाथभांशत्रिकोणमायाति तदा विवाहः ॥१२॥"], gloss: "The direction of the wife's home is that of the sign of the grahas in the 7th, the 7th lord and Venus. Marriage when Venus or the 7th lord comes in transit to the 5th or 9th from the navāṁśa of the lagna lord." },
    { chapter: 10, verse: 13, sanskrit: ["कलत्रसंस्थस्य कलत्रदृष्टेर्दशागमे वाऽथ कलत्रपस्य ।", "यदा विलग्नाधिपतिः प्रयाति कलत्रभं तत्र कलत्रलाभः ॥१३॥"], gloss: "In the daśā of a graha in the 7th, of one that aspects it or of the 7th lord, when the lagna lord goes to the sign of the 7th: the gain of a wife." },
    { chapter: 10, verse: 14, sanskrit: ["कलत्रनाथस्थितभांशकेशयोः सितक्षपानायकयोर्बलीयसः ।", "दशागमे द्यूनपयुक्तभांशत्रिकोणगे देवगुरौ करग्रहः ॥१४॥"], gloss: "In the daśā of the stronger of the lords of the sign and navāṁśa of the 7th lord, or of Venus and the Moon, when Jupiter goes to the 5th or 9th from the 7th lord: the marriage." },
    { chapter: 10, verse: 15, sanskrit: ["कलत्रनाथे रिपुनीचसंस्थे मूढेऽथवा पापनिरीक्षिते वा ।", "कलत्रभे पापयुतेऽथ दृष्टे कलत्रहानिं प्रवदन्ति सन्तः ॥१५॥"], gloss: "The 7th lord in an enemy sign or its fall, combust, or seen by malefics, or the 7th joined or seen by malefics: loss of the wife." },
  ],  11: [
    { chapter: 11, verse: 1, sanskrit: ["यद्यत्पुंप्रसवे क्षमं तदखिलं स्त्रीणां प्रिये वा वदे-", "न्माङ्गल्यं निधनात् सुतांश्च नवमाल्लग्नात्तनोश्चारुताम् ।", "भर्तारं सुभगत्वमस्तभवनात्सङ्गं सतीत्वं सुखात्", "सन्तस्तेषु शुभप्रदास्त्वशुभदाः क्रूरास्तदीशं विना ॥१॥"], gloss: "What is said for a man is said for a woman too; but the luck of the marriage (māṅgalya) is seen from the 8th, children from the 9th, the body and its charm from the lagna, the husband and good fortune from the 7th, chastity and other men from the 4th. Benefics in them give good, malefics ill, except the lord of the house itself." },
    { chapter: 11, verse: 2, sanskrit: ["उदयहिमकरौ द्वौ युग्मगौ सौम्यदृष्टौ", "सुतनयपतिभूषासम्पदुत्कृष्टशीला ।", "अशुभसहितदृष्टौ चोजगौ पुंस्वभावा", "कुटिलमतिरवश्या भर्तुरुग्रा दरिद्रा ॥२॥"], gloss: "The lagna and the Moon sign both even and seen by benefics: she has good sons, a fine husband, ornaments, wealth and excellent character. Both odd and joined or seen by malefics: she is of a masculine nature, crooked, wilful, fierce to her husband, poor." },
    { chapter: 11, verse: 3, sanskrit: ["सद्राश्यंशयुते मदे द्युतियशोविद्यार्थवांस्तत्पति-", "र्व्यत्यस्ते कुतनुर्जडश्च कितवो निःस्वो वियोगस्तयोः ।", "आग्नेयैर्मदनस्थितैश्च विधवा मिश्रैः पुनर्भूर्भवेत्", "क्रूरेष्वायुषि भर्तृहन्त्र्यपि धने सन्तः स्वयं स्त्रीमृतिः ॥३॥"], gloss: "The 7th a benefic's sign and navāṁśa: her husband is bright, famous, learned and rich; the reverse: ugly, dull, a cheat, poor, and they part. Mars in the 7th: a widow; benefics and malefics both there: she marries again. Malefics in the 8th: the death of the husband; benefics in the 2nd: her own death comes first." },
    { chapter: 11, verse: 4, sanskrit: ["सुतस्थेऽलिस्त्रीगोहरिषु हिमगौ चाल्पतनया", "यमारार्काशक्षें मदनसदने सामयभगा ।", "सुखे पापैर्युक्ते भवति कुलटा मन्दकुजयो-", "र्गृहेंऽशे लग्नेन्दू भृगुरपि च पुंश्चल्यभिहिता ॥४॥"], gloss: "The Moon in the 5th in Scorpio, Virgo, Taurus or Leo: few children. The sign or navāṁśa of Saturn or Mars in the 7th: disease of the womb. Malefics in the 4th: unchaste. The lagna, the Moon and Venus in the sign or navāṁśa of Mars or Saturn: of loose conduct.", note: "Some letters of the second line were misread in the scan and are corrected from the commentary." },
    { chapter: 11, verse: 5, sanskrit: ["शुभक्षेत्रांशेऽस्ते सुभगजघना मङ्गलवती", "विधोः सत्सम्बन्धेऽप्युदयसुखयोः साध्व्यतिगुणा ।", "…", "बलोनाः क्रूराश्चेद्यदि भवति वन्ध्या मृतसुता ॥५॥"], gloss: "The 7th a benefic's sign and navāṁśa: she is fair and fortunate. The Moon, the lagna and the 4th with benefics: virtuous and of many qualities. Benefics in the 5th and 9th: children, happiness and virtue. Weak malefics there: barren, or her children die.", note: "One line of the verse could not be read in the scan." },
    { chapter: 11, verse: 6, sanskrit: ["चन्द्रे भौमगृहे कुजादिकथितत्रिंशांशकेषु क्रमात्", "दुष्टा दास्यसती सुशीलविभवा मायाविनी दूषणी ।", "शुक्रक्षे बहुदूषणान्यपतिगा पूज्या सुधीर्विश्रुता", "…साध्वी गुणाढ्योत्सुका ॥६॥"], gloss: "The Moon (and the lagna, 11.8) in the trimshāṁśa of Mars, Saturn, Jupiter, Mercury, Venus, by the sign: in a sign of Mars wicked, a servant and unchaste, virtuous and rich, crafty, faulty; in a sign of Venus unchaste, fond of other men, honoured, learned, famous; in Gemini or Virgo crafty, like a eunuch, virtuous, of many qualities, fond of pleasure.", note: "Part of the last line could not be read in the scan." },
    { chapter: 11, verse: 7, sanskrit: ["स्वच्छन्दा भर्तृघातिन्यतिमहितगुणा शिल्पिनी साधुवृत्ता", "चान्द्रे जैवे गुणाढ्या विरतिरतिगुणा ज्ञातशिल्पातिसाध्वी ।", "मान्दे दास्यन्यसक्ताश्रितपतिरसती निष्प्रजार्थार्कभे स्याद्", "दुर्भार्या हीनवृत्ता धरणिपतिवधूः पुंविचेष्टान्यसक्ता ॥७॥"], gloss: "The same in Cancer (wilful, a killer of her husband, of great qualities, skilled in crafts, virtuous); in Sagittarius or Pisces (of good qualities, cold, very virtuous, an artist, very devout); in Capricorn or Aquarius (a servant, fond of others, her husband dependent on her, unchaste, childless); in Leo (wicked, base, a queen, acting like a man, fond of others)." },
    { chapter: 11, verse: 8, sanskrit: ["शशिलग्नसमायुक्तैः फलं त्रिंशांशकैरिदम् ।", "बलाबलविकल्पेन तयोरेवं विचिन्तयेत् ॥८॥"], gloss: "This is the result of the trimshāṁśas joined to the Moon and the lagna; it is to be weighed by the strength and weakness of the two." },
    { chapter: 11, verse: 9, sanskrit: ["ज्येष्ठं भ्रातरमम्बिकां च पितरं भर्तुः कनिष्ठं क्रमात्", "ज्येष्ठाह्यासुरशूर्पजाश्च वनिता घ्नन्तीति तज्ज्ञा विदुः ।", "चित्रार्द्राभुजगस्वराट्छतभिषङ्मूलाग्नितिष्योद्भवा", "बन्ध्या वा विधवाथवा मृतसुता त्यक्ता प्रियेणाधना ॥९॥"], gloss: "A woman born in Jyeṣṭhā, Āśleṣā, Mūla or Viśākhā kills, in that order, the husband's elder brother, his mother, his father or his younger brother. Born in Citrā, Ārdrā, Āśleṣā, Śatabhiṣā, Jyeṣṭhā, Mūla, Kṛttikā or Puṣya: barren, a widow, her children die, abandoned by her love, poor.", note: "The names of the nakṣatras in the second line are in code (the first letters of their gods) and are read as the commentary reads them." },
    { chapter: 11, verse: 10, sanskrit: ["चन्द्रास्तोदयभाग्यपाः सह शुभैः सुस्थानगा भास्वराः", "पूज्या बन्धुषु पुण्यकर्मकुशला सौन्दर्यभाग्यान्विता ।", "भर्तुः प्रीतिकरी सुपुत्रसहिता कल्याणशीला सती", "तावद्भाति सुमङ्गली च सुतनुर्यावच्छुभाढ्येऽष्टमे ॥१०॥"], gloss: "The lords of the Moon sign, the lagna, the 7th and the 9th joined or seen by benefics, well placed and not combust: she is honoured among her kin, fair and fortunate, dear to her husband, with good sons, virtuous. Her happy married life lasts as long as the 8th is rich in benefics." },
    { chapter: 11, verse: 11, sanskrit: ["शीतज्योतिषि योषितोऽनुपचयस्थाने कुजेनेक्षिते", "जातं गर्भफलप्रदं खलु रजः स्यादन्यथा निष्फलम् ।", "दृष्टेऽस्मिन् गुरुणा निजोपचयगे कुर्यान्निषेकं पुमान्", "अत्याज्ये समये शुभाधिकयुते पर्वादिकालोज्झिते ॥११॥"], gloss: "When the Moon, in a house that is not an upacaya from the lagna, is seen by Mars at the woman's menses, the month bears fruit; otherwise not. A man wishing for a son should conceive when the transit Moon is in an upacaya from his birth chart and seen by Jupiter, not on the parva days." },
  ],
  12: [
    { chapter: 12, verse: 1, sanskrit: ["सुस्था विलग्नशशिनोः सुतभेशजीवाः", "सुस्थाननाथशुभदृष्टियुते सुतर्क्षे ।", "लग्नात्मपौ यदि युतौ च मिथः सुदृष्टौ", "क्षेत्रे परस्परगतौ यदि पुत्रसिद्धिः ॥१॥"], gloss: "Children: the 5th lords from the lagna and the Moon and Jupiter well placed, the two 5ths joined or seen by benefics and by lords of good houses, the lagna lord and the 5th lord joined, in aspect or in each other's signs." },
    { chapter: 12, verse: 2, sanskrit: ["लग्नामरेड्यशशिनां सुतभेषु पापै-", "… शुभैरयुतेक्षितेषु ।", "पापोभयेषु सुतभेषु सुतेश्वरेषु", "दुस्थानगेषु न भवन्ति सुताः कथञ्चित् ॥२॥"], gloss: "No children: the 5ths from the lagna, Jupiter and the Moon joined or seen by malefics and not by benefics, between malefics, and their lords in the 6th, 8th or 12th.", note: "The first half of the second line is lost in the scan." },
    { chapter: 12, verse: 3, sanskrit: ["पापे स्वर्क्षगते सुते तनयभाक् तस्मिन् सपापे पुनः", "पुत्राः स्युर्बहुलाः शुभस्वभवने सोग्रे सुते पुत्रहा ।", "संज्ञां चाल्पसुतर्क्षमित्यलिवृषस्त्रीसिंहभानां विदः", "तद्राशौ सुतभावगेऽल्पसुतवान् कालान्तरेऽसाविति ॥३॥"], gloss: "A malefic in its own sign in the 5th: children; with another malefic: many sons; the 5th a sign of a benefic with a malefic in it: loss of sons. Scorpio, Taurus, Virgo and Leo are the signs of few sons: late and few children when one of them is the 5th.", note: "The word \"विदः\" is restored from a misreading of the scan." },
    { chapter: 12, verse: 4, sanskrit: ["सूर्ये चाल्पसुतक्षगे निधनगे मन्दे कुजे लग्नगे", "लग्नाष्टव्ययगैः शनीड्यरुधिरैश्चाल्पात्मजक्षे सुते ।", "चन्द्रे लाभगते गुरुस्थितसुतस्थाने सपापे भवे-", "ल्लग्नेऽनेकखगान्विते तनयभाक्कालान्तरे यत्नतः ॥४॥"], gloss: "Children late and by effort: the Sun in a sign of few sons, Saturn in the 8th, Mars in the lagna; or Saturn, Jupiter and Mars in the lagna, 8th and 12th with the 5th a sign of few sons; or the Moon in the 11th, the 5th from Jupiter with a malefic and many grahas in the lagna." },
    { chapter: 12, verse: 5, sanskrit: ["सूर्ये नान्ययुते सुतर्क्षसहिते चन्द्रस्य गेहे स्थिते", "भौमे वा भृगुजेऽपि वा सति सुतप्राप्तिर्द्वितीयस्त्रियाम् ।", "मन्दे वा बहुपुत्रवाञ्छशिनि वा सौम्येऽपि वाल्पात्मजो", "देवेड्ये बहुदारिका शशिगृहे तद्वत्सुताधिष्ठिते ॥५॥"], gloss: "The 5th Cancer: the Sun alone, or Mars or Venus: children by a second wife; Saturn: many sons; the Moon or Mercury: few; Jupiter: many daughters." },
    { chapter: 12, verse: 6, sanskrit: ["सुखास्तदशमस्थितैरशुभकाव्यशीतांशुभि-", "रव्ययाष्टतनयोदयेष्वशुभगेषु वंशक्षयः ।", "मदे कविविदौ …", "सुते शशिनि नैधनव्ययतनुस्थपापैरपि ॥६॥"], gloss: "The line ends: a malefic, Venus and the Moon in the 4th, 7th and 10th; malefics in the 12th, 8th, 5th and lagna; Venus and Mercury in the 7th, Jupiter in the 5th, the 4th afflicted; the Moon in the 5th with malefics in the 8th, 12th and lagna.", note: "The third line is incomplete in the scan; the third yoga is read from the commentary." },
    { chapter: 12, verse: 7, sanskrit: ["पापे लग्ने लग्नपे पुत्रसंस्थे धीशे वीर्ये वेश्मनीन्दावपुत्रः ।", "ओजर्क्षेशे पुत्रगे सूर्यदृष्टे चन्द्रे पुत्रक्लेशभाक् स्यादसूनुः ॥७॥"], gloss: "Without sons: a malefic in the lagna, the lagna lord in the 5th, the 5th lord in the 3rd and the Moon in the 4th; and sorrow through a son: the Moon in the 5th in the navāṁśa of an odd sign, seen by the Sun." },
    { chapter: 12, verse: 8, sanskrit: ["मान्दं सुतर्क्षं यदि वाऽथवौधं मान्द्यर्कपुत्रान्वितवीक्षितं चेत् ।", "दत्तात्मजः स्यादुदयास्तनाथसम्बन्धहीनो विबलः सुतेशः ॥८॥"], gloss: "An adopted son: the 5th a sign of Saturn or Mercury joined or seen by Māndi and Saturn; or the 5th lord weak and unconnected with the lords of the lagna and the 7th." },
    { chapter: 12, verse: 9, sanskrit: ["नीचारिमूढोपगते सुतेशे रिःफारिरन्ध्राधिपसंयुते वा ।", "सुतस्य नाशः कथितोऽत्र तज्ज्ञैः शुभैरदृष्टे सुतभे सुतेशे ॥९॥"], gloss: "Loss of the son: the 5th lord in its fall, in an enemy sign or combust, or with the lords of the 12th, 6th or 8th; or the 5th lord in the 5th unseen by benefics." },
    { chapter: 12, verse: 10, sanskrit: ["सुतनाथजीवकुजभास्करेषु वै", "पुरुषांशकेषु च गतेषु कुत्रचित् ।", "मुनयो वदन्ति बहुपुत्रतां तदा", "सुतनाथवीर्यवशतः सुपुत्रताम् ॥१०॥"], gloss: "Many sons: the 5th lord, Jupiter, Mars and the Sun anywhere in male navāṁśas; good sons by the strength of the 5th lord." },
    { chapter: 12, verse: 11, sanskrit: ["पुंराश्यंशेऽधीश्वरे पुंग्रहेन्द्रैर्युक्ते दृष्टे … पुंप्रसूतिः ।", "स्त्रीराश्यंशे स्त्रीग्रहैर्युक्तदृष्टे स्त्रीणां जन्म स्यात्सुतक्षे सुतेशे ॥११॥"], gloss: "A son or a daughter: the 5th lord in a male sign and navāṁśa, joined or seen by male grahas: a son; in a female sign and navāṁśa, joined or seen by female grahas: a daughter.", note: "A word of the first line is lost in the scan." },
    { chapter: 12, verse: 12, sanskrit: ["बलयुक्तौ स्वगृहांशेष्वर्कसितावुपचयर्क्षगौ पुंसाम् ।", "स्त्रीणां वा कुजचन्द्रौ यदा तदा सम्भवति गर्भः ॥१२॥"], gloss: "Conception: in a man's chart the Sun and Venus strong in their own sign and navāṁśa in an upacaya house; in a woman's Mars and the Moon." },
    { chapter: 12, verse: 13, sanskrit: ["आशत्रुनीचारिनवांशकैः सुते सुतेशयुक्तैरपि तैस्तथाविधैः ।", "सुतर्क्षगैर्वा गुरुभादिनांशकात् सुते फलैः पुत्रमिति विचिन्त्यते ॥१३॥"], gloss: "The number of children from the grahas with the 5th and its lord and from the 5th from Jupiter, by friendly, enemy and fallen navāṁśas." },
    { chapter: 12, verse: 14, sanskrit: ["जीवेन्दुक्षितिजस्फुटैक्यभवने युग्मे च युग्मांशके", "स्त्रीणां क्षेत्रबलं वदन्ति सुतदं मिश्रे प्रयासात्फलम् ।", "भास्वच्छुक्रगुरुस्फुटैक्यभवनेऽप्योजांशकेऽप्योजभे", "पुंसां बीजबलं सुतप्रदमिमं मिश्रे तु मिश्रं वदेत् ॥१४॥"], gloss: "The field and the seed: the sum of the longitudes of Jupiter, the Moon and Mars in an even sign and navāṁśa gives a woman the strength of the field; the sum of the Sun, Venus and Jupiter in an odd sign and navāṁśa gives a man the strength of the seed; mixed: the fruit by effort." },
    { chapter: 12, verse: 15, sanskrit: ["पञ्चघ्नाच्छशिनः स्फुटादिषुहतं भानुस्फुटं शोधये-", "न्नीत्वा तत्र तिथिं सिते शुभतिथौ पुत्रोऽस्त्ययत्नादपि ।", "कृष्णे नास्ति सुतस्तिथेर्बलवशाद् ब्रूयाद् द्वयोः पक्षयोः", "दर्शे च्छिद्रतिथौ च विष्टिकरणे न स्यात् स्थिराख्ये सुतः ॥१५॥"], gloss: "A reckoning from the Moon and the Sun that gives a tithi: a son without effort in a good tithi of the bright half; none in the dark half, on the new moon, a tithi of a gap, in Viṣṭi or a fixed karaṇa.", note: "A word of the first line is restored from a misreading of the scan." },
    { chapter: 12, verse: 16, sanskrit: ["विष्टिः स्थिरं वा करणं यदि स्यात् कृष्णा यजेत् पौरुषसूक्तमन्त्रैः ।", "षष्ठ्यां गुहाराधनमत्र कार्यं यजेच्चतुर्थ्यां किल नागराजम् ॥१६॥"], gloss: "Remedy by the tithi: with Viṣṭi, a fixed karaṇa or the dark half the Puruṣa-sūkta is used; on the 6th Guha is worshipped, on the 4th the king of serpents." },
    { chapter: 12, verse: 17, sanskrit: ["रामायणस्य श्रवणं नवम्यां यद्यष्टमी चेच्छ्रवणव्रतं च ।", "चतुर्दशी चेद्यदि रुद्रपूजा स्याद्द्वादशी चेत्स्मृतमन्नदानम् ॥१७॥"], gloss: "Remedy by the tithi: on the 9th the Rāmāyaṇa is heard, on the 8th the Śravaṇa vow, on the 14th Rudra is worshipped, on the 12th food is given." },
    { chapter: 12, verse: 18, sanskrit: ["तृप्तिं पितॄणामिह पञ्चदश्यां कृष्णे दशम्याः परतोऽतियत्नात् ।", "पक्षत्रिभागेष्वपि नागराजं स्कन्दं च सेवेत हरिं क्रमेण ॥१८॥"], gloss: "Remedy by the tithi: the forefathers are satisfied on the 15th and after the 10th of the dark half; in the three parts of the fortnight the king of serpents, Skanda and Hari are served in turn." },
    { chapter: 12, verse: 19, sanskrit: ["पुत्रेशो रिपुनीचगोऽस्तमयगो रिःफाष्टमारिस्थितः", "तद्वत्पुत्रगृहस्थितोऽपि यदि वा दुःस्थानपस्तद्वशात् ।", "पुत्राभावनिदानमेव कथयेत् तत्खेचराक्रान्तभ-", "रोक्तैर्दैवतभूरुहैरपि मृगैः सन्तानहेतुं वदेत् ॥१९॥"], gloss: "The cause of no children: the 5th lord in an enemy sign, in its fall, combust or in the 12th, 8th or 6th, or in the 5th, or lord of an evil house; the cause is told by the sign the afflicting graha holds, by deities, trees and animals." },
    { chapter: 12, verse: 20, sanskrit: ["द्रोहाच्छम्भुसुपर्णयोर्नहि सुतः शापात् पितॄणां रवे-", "रिन्दोर्मातृसुवासिनीभगवतीकोपान्मनोदोषतः ।", "स्वग्रामस्थितदेवतागुहरिपुज्ञात्युत्थदोषात्कुजे", "शापाद्वालकृताद्विडालवधतः श्रीविष्णुकोपाद् बुधे ॥२०॥"], gloss: "The cause by the graha: the Sun: the wrath of Śiva and Garuḍa or the curse of the forefathers; the Moon: the wrath of the mother, of a married woman or of the Goddess; Mars: the village deity, Guha, enemies and kin; Mercury: a child's curse, killing a cat, the wrath of Viṣṇu." },
    { chapter: 12, verse: 21, sanskrit: ["पारम्पर्यसुरप्रियद्विजगुरुद्रोहात्फलाढ्यद्रुम-", "च्छेदाद्देवगुरौ तथा सति भृगौ पुष्पद्रुमच्छेदनात् ।", "साध्वीगोकुलजातदोषवशतो यक्ष … सा", "मन्देऽश्वत्थवधाद्रुषा पितृपतेः प्रेतैः पिशाचादिभिः ॥२१॥"], gloss: "The cause by the graha: Jupiter: wronging a teacher or Brahmin, cutting a fruit tree; Venus: cutting a flowering tree, wronging a good woman or cattle; Saturn: felling the aśvattha, the wrath of Yama, spirits and goblins.", note: "A word of the third line is doubtful in the scan." },
    { chapter: 12, verse: 22, sanskrit: ["स्वर्भानौ सुतगे सुतेशसहिते सर्पस्य शापात्तथा", "केतौ ब्राह्मणशापतश्च गुलिके प्रेतोत्थशापं वदेत् ।", "शुक्रेन्दू गुलिकान्वितौ यदि वधूगोहत्तिमाहुः सुते", "जीवो वाथ शिखी समान्दिरिह चेद्भूदेवहत्याऽसुतः ॥२२॥"], gloss: "Rāhu in the 5th with the 5th lord: a serpent's curse; Ketu: a Brahmin's curse; Gulika: the curse of a spirit; Venus and the Moon with Gulika in the 5th: the killing of a woman or a cow; Jupiter or Ketu with Māndi: killing a Brahmin." },
    { chapter: 12, verse: 23, sanskrit: ["… हि जन्मसमये बहुपूर्वजन्म-", "कर्मार्जितं दुरितमस्य वदन्ति तज्ज्ञाः ।", "तत्तद्ग्रहोक्तजपदानशुभक्रियाभि-", "स्तद्दोषशान्तिमिह शंसतु पुत्रसिद्धयै ॥२३॥"], gloss: "The sin of earlier births shown at birth is quieted by the prayers, gifts and good deeds told for each graha, for the gaining of a son.", note: "The first word is lost in the scan." },
    { chapter: 12, verse: 24, sanskrit: ["सेतुस्नानं कीर्तनं सत्कथायाः पूजां शम्भोः श्रीपतेः सद्व्रतानि ।", "दानं श्राद्धं … नागप्रतिष्ठां कुर्यादेतैः प्राप्नुयात्सन्ततिं सः ॥२४॥"], gloss: "Remedies: a bath at Setu, praise and the telling of good tales, the worship of Śambhu and of Viṣṇu, vows, gifts, śrāddha and the setting up of a serpent: by these he gains offspring.", note: "A word of the second line is doubtful in the scan." },
    { chapter: 12, verse: 25, sanskrit: ["लग्नास्तपुत्रपतिजीवदशापहारे", "पुत्रेक्षकस्य सुतगस्य च पुत्रसिद्धिः ।", "पुत्रेशराशिमथवा यमकण्टकर्क्षं", "जीवे गते तनयसिद्धिरथांशभे वा ॥२५॥"], gloss: "The time of the son: in the daśā and antardaśā of the lords of the lagna, 7th and 5th, of Jupiter, of the graha seeing the 5th and of the graha in it; or when Jupiter goes to the sign of the 5th lord or of Yamakaṇṭaka, or to its navāṁśa." },
    { chapter: 12, verse: 26, sanskrit: ["लग्नाधीशः पुत्रनाथेन योगं स्वोच्चे स्वक्षे चारगत्या समेति ।", "पुत्रप्राप्तिः स्यात्तदा लग्ननाथः पुत्रर्क्षं वा याति धीशाप्तभं वा ॥२६॥"], gloss: "The time of the son by transit: the lagna lord joins the 5th lord, goes to its exaltation or own sign, to the 5th sign or to the sign of the 5th lord." },
    { chapter: 12, verse: 27, sanskrit: ["विलग्नकामात्मजनायकानां योगात्समानीय दशां महाख्याम् ।", "सुतस्थतद्वीक्षकतत्पतीनां दशापहारेषु सुतोद्भवः स्यात् ॥२७॥"], gloss: "The time of the son: the longitudes of the lords of the lagna, 7th and 5th added give a nakṣatra; in the daśā of its lord and the antardaśās of the graha in the 5th, the one seeing it and its lord a son is born." },
    { chapter: 12, verse: 28, sanskrit: ["सुतपतिगुर्वोरथवा तद्युक्तराश्यंशकाधिपानां वा ।", "बलसहितस्य दशायामपहारे वा सुतप्राप्तिः ॥२८॥"], gloss: "The time of the son: the daśā or antardaśā of the 5th lord and Jupiter (and of Mars, by the commentary), or of the lords of their signs and navāṁśas, the stronger one.", note: "The first half of the verse is incomplete in the scan; Mars is from the commentary." },
    { chapter: 12, verse: 29, sanskrit: ["जीवे तु जीवात्मजनाथभांशकत्रिकोणगे पुत्रजनिर्भवेन्नृणाम् ।", "अथान्यशास्त्रेण च जन्मकालतो निरूपयेत्सन्ततिलक्षणं बुधः ॥२९॥"], gloss: "The time of the son: Jupiter in a trine to the sign or navāṁśa of the lord of the 5th from Jupiter; the signs of offspring may also be found from other texts." },
    { chapter: 12, verse: 30, sanskrit: ["जन्मनक्षत्रनाथस्य प्रत्यर्याक्षाधिपस्य च ।", "स्फुटयोगं गते जीवे त्रिकोणे वा सुतोद्भवः ॥३०॥"], gloss: "The time of the son: Jupiter on the sum of the longitudes of the lord of the birth nakṣatra and of the lord of the 5th nakṣatra, or in a trine to it." },
    { chapter: 12, verse: 31, sanskrit: ["निषेकलग्नाद्दिनपस्तृतीये राशौ यदा चारवशादुपैति ।", "आधानलग्नादथवा त्रिकोणे रवौ यदा जन्म वदेन्नराणाम् ॥३१॥"], gloss: "The time of the son: the Sun by transit in the 3rd sign, or a trine, from the lagna of conception." },
    { chapter: 12, verse: 32, sanskrit: ["आधानलग्नात्सुतभेशजन्म भाग्येऽपि वा पुण्यवशाच्च वाच्यम् ।", "आधानलग्ने शुभदृष्टियोगे दीर्घायुरैश्वर्ययुतो नरः स्यात् ॥३२॥"], gloss: "A son born in the 5th or 9th from the lagna of conception is by merit; with benefics joining or seeing that lagna he is long-lived and rich." },
    { chapter: 12, verse: 33, sanskrit: ["तत्कालेन्दुद्वादशांशो मेषात्तावति भेऽपि वा ।", "तस्मात्तावति भे वाऽपि जन्मचन्द्रं वदेद्बुधः ॥३३॥"], gloss: "The birth Moon from the conception Moon: the sign counted from Aries (or from its own sign) as the number of its dvādaśāṁśa." },
    { chapter: 12, verse: 34, sanskrit: ["प्रश्नात्मजस्वीकरणोपनीतिकन्याप्रदानाभिनवार्तवेषु ।", "आधानकालेऽपि च जन्मतुल्यं फलं वदेज्जन्मविलग्नतश्च ॥३४॥"], gloss: "The lagna of the question, of adopting a son, of the thread ceremony, of giving a daughter, of the first menses and of conception is read like the birth lagna." },
  ],
  13: [
    { chapter: 13, verse: 1, sanskrit: ["जाते कुमारे सति पूर्वमायुर्विचिन्त्यं हि ततः फलानि ।", "विचारणीया गुणिनि स्थिते तद् गुणाः समस्ताः खलु लक्षणज्ञैः ॥१॥"], gloss: "When a child is born the length of life is first considered, and then the other results; all the merits rest on there being a life." },
    { chapter: 13, verse: 2, sanskrit: ["केचिद्यथाधानविलग्नमन्ये शीर्षोदयं भूपतनं हि केचित् ।", "होराविदश्चेतनकाययोन्योर्वियोगकालं कथयन्ति लग्नम् ॥२॥"], gloss: "Which moment is the birth: some take the lagna of conception, some the appearing of the head, some the touching of the ground, some the cutting of the cord, when the body and the womb part." },
    { chapter: 13, verse: 3, sanskrit: ["आद्वादशाब्दान्नरयोनिजन्मनामायुष्कला निश्चयितुं न शक्यते ।", "मात्रा च पित्रा कृतपापकर्मणा बालग्रहैर्निशिमुपैति बालकः ॥३॥"], gloss: "Up to twelve years the span of life of men cannot be settled: the child dies by the sins of its parents or by the child-seizing grahas." },
    { chapter: 13, verse: 4, sanskrit: ["आद्ये चतुष्के जननीकृताघैर्मध्ये च …", "…", "बालस्तदन्त्यासु चतुःशरत्सु स्वकीयदोषैः समुपैति नाशम् ॥४॥"], gloss: "In the first four years the child dies by the sins of the mother, in the middle four by those of the father, in the last four years by its own.", note: "Two lines are lost in the scan." },
    { chapter: 13, verse: 5, sanskrit: ["तद्दोषशान्त्यै प्रतिजन्मतारमाद्वादशाब्दं जपहोमपूर्वम् ।", "आयुष्करं कर्म विधाय तातो बालं चिकित्सादिभिरेव रक्षेत् ॥५॥"], gloss: "The father should quiet those faults every year on the birth star up to twelve years with prayers, fire rites and rites for long life, and guard the child with medicines." },
    { chapter: 13, verse: 6, sanskrit: ["अष्टौ बालारिष्टमादौ नराणां योगारिष्टं प्राहुराविंशतिः स्यात् ।", "अल्पं चाद्वात्रिंशतं मध्यमायुश्चासप्तत्याः पूर्णमायुः शतान्तम् ॥६॥"], gloss: "Eight years of the child's ariṣṭa, up to twenty the ariṣṭa of yogas; short life to thirty-two, middle life to seventy, full life to a hundred." },
    { chapter: 13, verse: 7, sanskrit: ["नृणां वर्षशतं ह्यायुस्तस्मिंस्त्रेधा विभज्यते ।", "अल्पं मध्यं दीर्घमायुरित्येतत्सर्वसम्मतम् ॥७॥"], gloss: "A hundred years is the span of men; in three parts it is the short, the middle and the long life, as all agree." },
    { chapter: 13, verse: 8, sanskrit: ["…", "मूलक्षे पितृमातृवंशविलयं तस्यान्त्यपादे श्रियं", "सार्पे व्यस्तमिदं फलं न शुभसम्बन्धं विलग्नं यदि ॥८॥"], gloss: "Birth in Mūla with the lagna unconnected with benefics: the quarters destroy the father, the mother, the whole family, the last gives wealth; in Āśleṣā the result is reversed. (The first half of the verse, on the days of death and disease and on Puṣya, Pūrvāṣāḍhā and Citrā, is lost in the scan.)", note: "The first half of the verse is lost in the scan." },
    { chapter: 13, verse: 9, sanskrit: ["पापाप्तेक्षितराशिसन्धिजनने सद्यो विनाशं …", "गण्डान्ते पितृमातृहा शिशुमृतिर्जीवेद्यदि क्ष्मापतिः ।", "जातः सन्धिचतुष्टयेऽप्यशुभसंयुक्तेक्षिते स्यान्मृति-", "र्मृत्योर्भागगते च सा सति विधौ केन्द्रेऽष्टमे वा मृतिः ॥९॥"], gloss: "Birth at the junction of signs with a malefic joined or seeing: quick death; at a gaṇḍānta: death of the father, the mother or the child, a king if it lives; at the four junctions with malefics: death; the Moon in its fatal degree in a kendra or the 8th: death.", note: "The end of the first line is not legible in the scan." },
    { chapter: 13, verse: 10, sanskrit: ["चान्द्रं रूपं लोकशूरो वरज्ञः कुड्ये चित्रं भाग्यलोके मुखानाम् ।", "मेने राज्यं मृत्युभागाः प्रदिष्टा मेषादीनां वर्णसंख्यैर्हिमांशोः ॥१०॥"], gloss: "The fatal degrees of the Moon in the signs from Aries, told in words that stand for numbers." },
    { chapter: 13, verse: 11, sanskrit: ["दानं धेनो रुद्र रौद्री मुखेन भाग्या भानुर्गोत्र जाया नखेन ।", "पुत्री नित्यं मृत्युभागाः क्रमेण मेषादीनां तेषु जातो गतायुः ॥११॥"], gloss: "Another list of fatal degrees of the Moon from Aries, in words for numbers; born in them, the life is gone." },
    { chapter: 13, verse: 12, sanskrit: ["रन्ध्रे केन्द्रेषु पापैरुदयनिधनगैर्वाथ लग्नास्तयोर्वा", "लग्नेऽब्जे वोग्रमध्ये व्ययमृतिरिपुगे दुर्बले शीतभानौ ।", "क्षीणेन्दौ साशुभे वा तनुमदगुरुधीभाजि रन्ध्रास्तगोग्रै-", "र्मृत्युः स्यादाशु केन्द्रे न यदि शुभखगाः सद्युतिर्वीक्षणं वा ॥१२॥"], gloss: "Quick death: malefics in the 8th and the kendras; malefics in the lagna and 8th, or the lagna and 7th; the lagna or the Moon between malefics; the weak Moon in the 12th, 8th or 6th; the waning Moon with malefics in the lagna, 7th, 9th or 5th; malefics in the 8th and 7th; unless benefics are in a kendra or join or see it." },
    { chapter: 13, verse: 13, sanskrit: ["जन्मेशोऽथ विलग्नपो यदि भवेद्दुःस्थोऽबलो वत्सरै-", "स्तद्राशिप्रमितैश्च मारयति तन्मासैर्दृगाणाधिपः ।", "अंशेशो दिवसैस्तथा यदि मृतिद्वित्र्यादियोगान्बहू-", "नालोच्य प्रवदेत्सुताष्टमगतैः पापैररिष्टं शिशोः ॥१३॥"], gloss: "The lord of the Moon sign or of the lagna, weak and in an evil house, kills in as many years as its sign; the lord of the decanate in as many months; the lord of the navāṁśa in as many days; with malefics in the 5th and 8th the ariṣṭa of the child." },
    { chapter: 13, verse: 14, sanskrit: ["लग्नेन्द्वोस्तदधीशयोरपि मिथो लग्नेशरन्ध्रेशयो-", "र्द्रेक्काणात्स्वनवांशकादपि मिथस्तद्द्वादशांशात्क्रमात् ।", "आयुर्दीर्घसमाल्पतां चरनगद्व्यङ्गैश्चरेऽथ स्थिरे", "ब्रूयाद्द्वन्द्वचरस्थिरैरुभयभैः स्थास्नुर्द्विदेहाटनैः ॥१४॥"], gloss: "Long, middle and short life from the kind of sign (movable, fixed, dual) in three pairs: the decanates of the lagna and the Moon, the navāṁśas of the lagna lord and the Moon-sign lord, the dvādaśāṁśas of the lagna lord and the 8th lord." },
    { chapter: 13, verse: 15, sanskrit: ["लग्नाधीशशुभाः क्रमाद्दृहुसमाल्पायूंषि केन्द्रादिगाः", "रन्ध्रेशोग्रखगास्तथा यदि गता व्यस्तं विदध्युः फलम् ।", "जन्मेशाष्टमनाथयोरुदयपच्छिद्रेशयोर्मैत्रतो", "भास्वल्लग्नपयोश्चिरायुरहिते ऽल्पायुः समे मध्यमः ॥१५॥"], gloss: "The lagna lord and the benefics in kendras, the succeeding or the cadent houses give long, middle and short life; the 8th lord and the malefics give it reversed. By friendship of the Moon-sign lord and its 8th lord, of the lagna lord and the 8th lord, of the Sun and the lagna lord: friends long life, enemies short, equals middle." },
    { chapter: 13, verse: 16, sanskrit: ["लग्नाधिपो लग्ननवांशनायको जन्मेश्वरो जन्मनवांशनायकः ।", "स्वस्वाष्टमेशाद्यदि चेद्बलान्वितो दीर्घायुषः स्युर्विपरीतमन्यथा ॥१६॥"], gloss: "The lagna lord and the lord of the lagna navāṁśa, the Moon-sign lord and the lord of the Moon navāṁśa, stronger than the lords of their 8ths: long life; otherwise the reverse." },
    { chapter: 13, verse: 17, sanskrit: ["लग्नेश्वरादतिबली निधनेश्वरोऽसौ", "केन्द्रस्थितो निधनरिःफगतैश्च पापैः ।", "तस्यायुरल्पमथवा यदि मध्यमायु-", "रुत्साहसङ्कटवशात्परमायुरेति ॥१७॥"], gloss: "The 8th lord stronger than the lagna lord in a kendra, with malefics in the 8th and 12th: short or middle life; the full span only through trouble and effort." },
    { chapter: 13, verse: 18, sanskrit: ["नरोऽल्पायुर्योगे प्रथमभगणे नश्यति शने-", "र्द्वितीये मध्यायुर्यदि भवति दीर्घायुषि सति ।", "तृतीये निर्याणं स्फुटजशनिगुर्वर्कहिमगून्", "दशां भुक्तिं कष्टामपि वदति निश्चित्य सुमतिः ॥१८॥"], gloss: "Death at Saturn's first, second or third round over the sum of the longitudes of Saturn, Jupiter, the Sun and the Moon, for the short, middle and long life; with an evil daśā and bhukti." },
    { chapter: 13, verse: 19, sanskrit: ["सपापो लग्नेशो रविहतरुचिर्नीचरिपुगो", "यदा दुःस्थानेषु स्थितिमुपगतो गोचरवशात् ।", "तनौ वा तद्योगो यदि निधनमाहुस्तनुभृतां", "नवांशाद्द्रेक्काणाच्छिशिरकरलग्नादपि वदेत् ॥१९॥"], gloss: "The lagna lord with malefics, combust, fallen or in an enemy sign, going by transit to an evil house or to the lagna: death; the same from the navāṁśa, the decanate and the Moon sign." },
    { chapter: 13, verse: 20, sanskrit: ["शशी तदारूढगृहाधिपश्च लग्नाधिनाथश्च यदा त्रयोऽमी ।", "गुणाधिकाः सद्ग्रहदृष्टियुक्ता गुणाधिकं तं कथयन्ति कालम् ॥२०॥"], gloss: "The Moon, the lord of its sign and the lagna lord, well placed in transit and joined or seen by benefics, give a time of much good." },
    { chapter: 13, verse: 21, sanskrit: ["लग्नाधिपोऽतिबलवानशुभैरदृष्टः", "केन्द्रस्थितः शुभखगैरवलोक्यमानः ।", "मृत्युं विहाय विदधाति स दीर्घमायुः", "सार्धं गुणैर्बहुभिरूर्जितराजलक्ष्म्या ॥२१॥"], gloss: "The lagna lord very strong, unseen by malefics, in a kendra and seen by benefics: long life, many good qualities and royal fortune." },
    { chapter: 13, verse: 22, sanskrit: ["सर्वातिशाय्यतिबलः स्फुरदंशुजालो", "लग्ने स्थितः प्रशमयेत् सुरराजमन्त्री ।", "एको बहूनि दुरितानि सुदुस्तराणि", "भक्त्या प्रयुक्त इव चक्रधरे प्रणामः ॥२२॥"], gloss: "Jupiter very strong in the lagna alone quiets many evils hard to cross, as one obeisance made in devotion to Viṣṇu does." },
    { chapter: 13, verse: 23, sanskrit: ["…", "ततस्त्रिकोणागमकण्टकेषु रवीन्दुजीवर्क्षनवांशसंस्थः ।", "…", "सुकर्मकृन्नित्यमशेषदोषान्मुष्णाति वर्द्धिष्णुरनुष्णरश्मिः ॥२३॥"], gloss: "The waxing Moon in a navāṁśa of the Sun, the Moon or Jupiter, in a trine, a kendra or the 11th, takes away all faults.", note: "Two lines are lost and one is displaced in the scan." },
    { chapter: 13, verse: 24, sanskrit: ["केन्द्रत्रिकोणनिधनेषु न यस्य पापा", "लग्नाधिपः सुरगुरुश्च चतुष्टयस्थौ ।", "भुक्त्वा सुखानि विविधानि सुपुण्यकर्मा", "जीवेच्च वत्सरशतं … विमुक्तरोगः ॥२४॥"], gloss: "No malefics in the kendras, trines and the 8th, the lagna lord and Jupiter in kendras: he enjoys many pleasures, free from disease, and lives a hundred years.", note: "A word of the last line is not legible in the scan." },
    { chapter: 13, verse: 25, sanskrit: ["श्रीपत्युदीरितदशाभिरथाष्टवर्गाद्", "यत्कालचक्रदशयोडुदशाप्रकारात् ।", "सम्यक्स्फुटाभिहतया क्रियया प्तवाक्या-", "दायुर्बुधो वदतु भूरिपरीक्षया च ॥२५॥"], gloss: "The span of life is to be told after much trial from the daśās of Śrīpati, the aṣṭakavarga, the Kālacakra and the Uḍu daśā and the exact longitudes.", note: "A word of the third line is doubtful in the scan." },
  ],
  14: [
    { chapter: 14, verse: 1, sanskrit: ["रोगस्य चिन्तामपि रोगभावस्थितैर्ग्रहैर्वा व्ययमृत्युसंस्थैः ।", "रोगेश्वरेणापि तदन्वितैर्वा द्वित्र्यादिसंवादवशाद्वदन्तु ॥१॥"], gloss: "Illness is read from the grahas in the 6th, in the 8th and 12th, and from the 6th lord and those joined to it; what two or three of these agree on is declared." },
    { chapter: 14, verse: 2, sanskrit: ["पित्तोष्णज्वरतापदेहतपनापस्मारहृत्क्रोडज-", "व्याधीन्वक्ति रविर्दृगार्त्यरिभयं त्वग्दोषमस्थिस्रुतिम् ।", "काष्ठाग्न्यस्रविषार्तिदारतनयव्यापच्चतुष्पाद्भयं", "चोरक्ष्मापतिधर्मदेवफणभृद्भूतेशभूतं भयम् ॥२॥"], gloss: "The Sun: bile, fever and burning, epilepsy, heart disease, pain in the eyes, fear of enemies, skin disease, bones, harm by wood, fire, weapons or poison, trouble for wife and children, fear of beasts, thieves, kings, Yama, serpents and Rudra." },
    { chapter: 14, verse: 3, sanskrit: ["निद्रालस्यकफातिसारपिटकाः शीतज्वरं चन्द्रमाः", "शृङ्गयब्जाहतिमग्निमान्द्यमरुचिं योषिद्व्यथाकामिलाः ।", "चेतःशान्तिमसृग्विकारमुदकाद्भीतिं च बालग्रहाद्", "दुर्गाकिन्नरधर्मदेवफणभृद्यक्ष्याश्च भीतिं वदेत् ॥३॥"], gloss: "The Moon: sleep and sloth, phlegm, diarrhoea, boils, cold fever, harm from horned beasts or water creatures, weak digestion, loathing of food, women's troubles, jaundice, a troubled mind, blood disease, fear of water, of child-seizing grahas, of Durgā, Yama, serpents and yakṣiṇīs." },
    { chapter: 14, verse: 4, sanskrit: ["तृष्णासृक्कोपपित्तज्वरमनलविषास्त्रार्तिकुष्ठाक्षिरोगान्", "गुल्मापस्मारमज्जाविहतिपरुषतापामिकादेहभङ्गान् ।", "भूपारिस्तेनपीडां सहजसुतसुहृद्वैरियुद्धं विधत्ते", "रक्षोगन्धर्वघोरग्रहभयमवनीसूनुरूर्ध्वाङ्गरोगम् ॥४॥"], gloss: "Mars: thirst, blood disease, bilious fever, harm by fire, poison or weapons, leprosy, eye disease, tumours, epilepsy, marrow, roughness of the body, itch, loss of limbs, trouble from kings, enemies and thieves, quarrels with brothers, sons, friends and foes, fear of demons and gandharvas, diseases of the upper body." },
    { chapter: 14, verse: 5, sanskrit: ["भ्रान्तिं दुर्वचनं दृगामयगलघ्राणोत्थरोगं ज्वरं", "पित्तश्लेष्मसमीरजं विषमपि त्वग्दोषपाण्ड्वामयान् ।", "दुःस्वप्नं च विचर्चिकाग्निपतने पारुष्यबन्धश्रमान्", "गन्धर्वक्षितिहर्म्यवाहिभिरपि ज्ञो वक्ति पीडां ग्रहैः ॥५॥"], gloss: "Mercury: delusion, bad speech, diseases of the eyes, throat and nose, fever, disorders of bile, phlegm and wind, poison, skin disease, jaundice, bad dreams, itch, falling in fire, harshness, bondage, weariness, trouble from gandharvas and other spirits." },
    { chapter: 14, verse: 6, sanskrit: ["गुल्मान्त्रज्वरशोकमोहकफजान् श्रोत्रार्तिमोहामयान्", "देवस्थाननिधिप्रपीडनमहीदेवेशशापोद्भवम् ।", "रोगं किन्नरयक्षदेवफणभृद्विद्याधराद्युद्भवं", "जीवः सूचयति स्वयं बुधगुरूत्कृष्टापचारोद्भवम् ॥६॥"], gloss: "Jupiter: tumours, fever of the bowels, grief, fainting and the diseases of phlegm, pain in the ears, delusion, trouble over temples and treasure, a Brahmin's curse, trouble from kinnaras, yakṣas, serpents and vidyādharas, and from wrong done to the learned and to teachers." },
    { chapter: 14, verse: 7, sanskrit: ["पाण्डुश्लेष्ममरुत्प्रकोपनयनव्यापन्मेहामयान्", "…", "वारस्त्रीकृतदेहकान्तिविहतिं शोषामयं योगिनी-", "यक्षीमातृगणाद्भयं प्रियसुहृद्भङ्गं सितः सूचयेत् ॥७॥"], gloss: "Venus: jaundice, disorders of wind and phlegm, eye disease, urinary disease and diabetes, trouble of the sexual organs, weakness, loss of lustre by harlots, consumption, fear of yoginīs, yakṣiṇīs and the mothers, a break with a dear friend.", note: "One line is lost in the scan." },
    { chapter: 14, verse: 8, sanskrit: ["वातश्लेष्मविकारपादविहतिं चापत्तितन्द्राश्रमान्", "भ्रान्तिं कुक्षिरुगन्तरुष्णभृतकध्वंसं च पार्श्वव्यथाम् ।", "भार्यापुत्रविपत्तिमङ्गविहतिं हृत्तापमर्कात्मजो", "वृक्षाश्मक्षतिमाह कश्मलगणैः पीडां पिशाचादिभिः ॥८॥"], gloss: "Saturn: disorders of wind and phlegm, lameness, calamity, drowsiness and weariness, delusion, pain in the belly and the sides, the loss of servants, harm to wife and sons, loss of limbs, pain in the heart, harm from trees or stones, trouble from goblins and piśācas." },
    { chapter: 14, verse: 9, sanskrit: ["स्वर्भानुर्हृदि तापकुष्ठविमतिव्याधिं विषं कृत्रिमं", "पादार्तिं च पिशाचपन्नगभयं भार्यातनूजापदम् ।", "ब्रह्मक्षत्रविरोधशत्रुजभयं केतुस्तु संसूचयेत्", "प्रेतोत्थं च भयं विषं च गुलिको देहार्तिमाशौचजम् ॥९॥"], gloss: "Rāhu: pain in the heart, leprosy, a clouded mind, poison, pain in the feet, fear of piśācas and serpents, trouble for wife and children; Ketu: opposition of Brahmins and warriors, fear of enemies; Gulika: fear of ghosts, poison, pain of the body, impurity from death." },
    { chapter: 14, verse: 10, sanskrit: ["मन्दारान्वितवीक्षिते व्ययधने चन्द्रारुणौ चाक्षिरुक्", "शौर्यायाङ्गिरसो यमारसहिता दृष्टा यदि श्रोत्ररुक् ।", "सोग्रे पञ्चमभे भवेदुदररुग्रन्ध्रारिनाथान्विते", "तद्वत्सप्तमनैधने सगुदरुक् शुक्रे च गुह्यामयः ॥१०॥"], gloss: "Disease of the eye: the Sun or the Moon in the 12th or 2nd joined or seen by Mars and Saturn; of the ear: the 3rd, the 11th and Jupiter with or seen by Mars and Saturn; of the belly: Mars with the 6th or 8th lord in the 5th; of the anus: the 6th and 8th lords in the 7th, and of the sexual parts if Venus is there too." },
    { chapter: 14, verse: 11, sanskrit: ["षष्ठेऽर्केऽप्यथवाष्टमे ज्वरभयं भौमे च केतौ व्रणं", "शुक्रे गुह्यरुजं क्षयं सुरगुरौ मन्दे च वातामयम् ।", "राहौ भौमनिरीक्षिते च पिलकां सेन्दौ शनौ गुल्मजं", "क्षीणेन्दौ जलभेषु पापसहिते तत्स्थेऽम्बुरोगं क्षयम् ॥११॥"], gloss: "In the 6th or 8th: the Sun, fear of fever; Mars or Ketu, wounds; Venus, disease of the sexual parts; Jupiter, consumption; Saturn, wind disease; Rāhu seen by Mars, boils; Saturn with the Moon, tumours; the waning Moon in a water sign with a malefic, water disease and consumption." },
    { chapter: 14, verse: 12, sanskrit: ["जातो गच्छति येन केन मरणं वक्ष्येऽथ तत्कारणं", "रन्ध्रस्थैस्तदवेक्षकैर्बलवता तस्योक्तरोगैर्मृतिः ।", "रन्ध्रर्क्षोक्तरुजाथवा मृतिपतिप्राप्तर्क्षदोषेण वा", "रन्ध्रेशेन खरत्रिभागपतिना मृत्युं वदेन्निश्चितम् ॥१२॥"], gloss: "The cause of death: by the diseases told for the strongest of the grahas in the 8th and those seeing it; or by the disease of the sign of the 8th; or of the sign where the 8th lord is; or by the 8th lord, or the lord of the Khara decanate." },
    { chapter: 14, verse: 13, sanskrit: ["ग्रहेण युक्ते निधने तदुक्तरोगैर्मृतिर्वाथ तदीक्षकस्य ।", "ग्रहैर्विमुक्ते निधनेऽथ तस्य राशेः स्वभावोदितदोषजाता ॥१३॥"], gloss: "With a graha in the 8th, death by its diseases or those of the graha seeing it; with none, by the fault told for the nature of the sign." },
    { chapter: 14, verse: 14, sanskrit: ["अग्न्युष्णज्वरपित्तशस्त्रजमिनश्चन्द्रो विषूच्यम्बुरुक्", "यक्ष्मादि क्षितिजोऽसृजा च दहनक्षुद्राभिचारायुधैः ।", "पाण्ड्वादि भ्रमजं बुधो गुरुरनायासेन मृत्युं कफात्", "स्त्रीसङ्गोत्थरुजं कविस्तु मरुता वा सन्निपातैः शनिः ॥१४॥"], gloss: "Death by the graha: the Sun, fire, fever, bile, weapons; the Moon, cholera, dropsy; Mars, blood, fire, magic, weapons; Mercury, jaundice and the like, delirium; Jupiter, easily, by phlegm; Venus, diseases from women; Saturn, wind or the three humours together." },
    { chapter: 14, verse: 15, sanskrit: ["कुष्ठेन वा कृत्रिमभक्षणाद्वा राहुर्विषाद्वाथ मसूरिकाद्यैः ।", "कुर्याच्छिखी दुर्मरणं नराणां रिपोर्विरोधादपि कीटकाद्यैः ॥१५॥"], gloss: "Rāhu: leprosy, poisoned food, poison, smallpox; Ketu: an evil death, by an enemy's quarrel, by insects." },
    { chapter: 14, verse: 16, sanskrit: ["लग्नादष्टमराशेः स्वभावदोषोद्भवं वदेन्मृत्युम् ।", "निधनेशस्य नवांशस्थितराशिनिमित्तदोषजनितं वा ॥१६॥"], gloss: "Death by the fault of the nature of the 8th sign from the lagna, or of the sign of the navāṁśa of the 8th lord." },
    { chapter: 14, verse: 17, sanskrit: ["पैत्त्यज्वरोष्णैर्जठराग्निनाजे वृषे त्रिदोषैर्दहनाच्च शस्त्रात् ।", "युग्मे तु कासश्वसनोष्णशूलैरुन्मादवातारुचिभिः कुलीरे ॥१७॥"], gloss: "By the sign: Aries, bilious fever, heat and the fire of the belly; Taurus, the three humours, burning, weapons; Gemini, cough, breathlessness, heat and colic; Cancer, madness, wind, loathing of food." },
    { chapter: 14, verse: 18, sanskrit: ["मृगज्वरस्फोटजशत्रुजं हरौ स्त्रियां स्त्रिया गुह्यरुजा प्रपातनात् ।", "तुलाधरे धीज्वरसन्निपातजं प्लीहालिपाण्डुग्रहणीरुजालिनि ॥१८॥"], gloss: "By the sign: Leo, beasts, fever, boils, an enemy; Virgo, women, disease of the sexual parts, a fall; Libra, brain fever and the three humours; Scorpio, the spleen, jaundice, sprue." },
    { chapter: 14, verse: 19, sanskrit: ["वृक्षाम्बुकाष्ठायुधजं हयाङ्गे मृगे तु शूलारुचिधीभ्रमाद्यैः ।", "कुम्भे तु कासज्वरयक्ष्मरोगैर्जले विपद्वा जलरोगतोऽन्त्ये ॥१९॥"], gloss: "By the sign: Sagittarius, a tree, water, wood, weapons; Capricorn, colic, loathing of food, a clouded mind; Aquarius, cough, fever, consumption; Pisces, death in water or by a water disease." },
    { chapter: 14, verse: 20, sanskrit: ["पापर्क्षयुक्ते निधने सपापे शस्त्रानलव्याघ्रभुजङ्गपीडा ।", "अन्योन्यदृष्टौ द्व्यशुभौ सकेन्द्रौ कोपान्नृभोः शस्त्रविषाग्निजैर्वा ॥२०॥"], gloss: "The 8th a sign of a malefic with a malefic in it: weapons, fire, tigers, serpents; two malefics in kendras seeing each other: the wrath of a king, weapons, poison, fire." },
    { chapter: 14, verse: 21, sanskrit: ["सौम्यांशके सौम्यगृहेऽथ सौम्यसम्बन्धगे वा क्षयभे क्षयेशे ।", "अक्लेशजातं मरणं नराणां व्यस्ते तदा क्रूरमृतिं वदन्ति ॥२१॥"], gloss: "The 12th sign and its lord, and the navāṁśa, in benefic signs or joined to benefics: a death without pain; the reverse: a cruel death." },
    { chapter: 14, verse: 22, sanskrit: ["स्वोच्चे स्वमित्रे सति सौम्यवर्गे व्ययाधिपे चोर्ध्वगतिं ससौम्ये ।", "विपर्ययेऽधोगतिमेव केचिदूर्ध्वास्यशीर्षोदयराशिभेदात् ॥२२॥"], gloss: "The 12th lord in its exaltation, in a friend's sign or in a benefic's varga, or with a benefic: the way upward; the reverse: the way downward. Some say it is by the sign of the 12th: upward-facing and head-rising, or not." },
    { chapter: 14, verse: 23, sanskrit: ["कैलासं रविशीतगू भृगुसुतः स्वर्गं महीजो महीं", "वैकुण्ठं शशिजो यमो यमपुरं सद्ब्रह्मलोकं गुरुः ।", "द्वीपान् भोगिवरः शिखी तु निरयं सम्प्रापयेत्प्राणिनः", "सम्बन्धाद्व्ययनायकस्य कथयेत्तत्रान्त्यराश्यंशतः ॥२३॥"], gloss: "The place after death by the 12th lord, the grahas in the 12th and in its navāṁśa: the Sun and Moon, Kailāsa; Venus, heaven; Mars, the earth; Mercury, Vaikuṇṭha; Saturn, the city of Yama; Jupiter, the world of Brahmā; Rāhu, the islands; Ketu, hell." },
    { chapter: 14, verse: 24, sanskrit: ["धर्मेश्वरेणैव हि पूर्वजन्म वृत्तं भविष्यज्जननं सुतेशात् ।", "तदीशजातिं तदधिष्ठितर्क्षं दिशं हि तत्रैव तदीशदेशम् ॥२४॥"], gloss: "The former birth is told by the 9th lord, the next by the 5th lord: the caste of the lord, the sign it holds, its direction and the country of its lord." },
    { chapter: 14, verse: 25, sanskrit: ["स्वोच्चे तदीशे सति देवभूमिं द्वीपान्तरं नीचरिपुस्थलस्थे ।", "स्वक्षे सुहृद्भे समभे स्थिते वा सम्प्राप्नुयाद्भारतवर्षमेव ॥२५॥"], gloss: "That lord in its exaltation: the land of the gods; in its fall or an enemy's sign: another island; in its own, a friend's or a neutral sign: only Bhāratavarṣa." },
    { chapter: 14, verse: 26, sanskrit: ["आर्यावर्तं गीष्पतेः पुण्यनद्यः काव्येन्द्वोश्च ज्ञस्य पुण्यस्थलानि ।", "… निन्द्या म्लेच्छभूस्तीक्ष्णभानोः शैलारण्यं कीकटं भूमिजस्य ॥२६॥"], gloss: "The country by the graha: Jupiter, Āryāvarta; Venus and the Moon, the land of holy rivers; Mercury, holy places; Saturn, a despised land of mlecchas; the Sun, hills and forest; Mars, Kīkaṭa.", note: "A word of the second line is not legible in the scan." },
    { chapter: 14, verse: 27, sanskrit: ["स्थिरे स्थिरांशाधिगतः सपापः पृष्ठोदयेऽधोमुखभे च संस्थः ।", "तदीश्वरो वृक्षलतादिजन्म स्यादन्यथा जीवयुतः शरीरी ॥२७॥"], gloss: "The 9th or 5th lord in a fixed sign or navāṁśa with a malefic, in a back-rising or downward-facing sign: birth as a tree or a creeper; otherwise a living body." },
    { chapter: 14, verse: 28, sanskrit: ["लग्नेशितुः स्वोच्चसुहृत्स्वगेहान् तदीश्वरो याति मनुष्यजन्म ।", "समे मृगाः स्युर्विहगाः परस्मिन् द्रेक्काणरूपैरपि चिन्तनीयम् ॥२८॥"], gloss: "That lord in the exaltation, a friend's or the own sign of the lagna lord: a human birth; in a neutral one: beasts; in an enemy's: birds; the decanates are also to be considered." },
    { chapter: 14, verse: 29, sanskrit: ["तावेकराशौ जननं स्वदेशे तौ तुल्यवीर्यौ यदि तुल्यजातौ ।", "वर्णो गुणस्तस्य खगस्य … संज्ञोदितैरेव वदेत्समस्तम् ॥२९॥"], gloss: "The two lords in one sign: birth in one's own country; of equal strength: of the same caste; the colour and the nature by the signs told in the chapter on the names.", note: "A word of the second line is not legible in the scan." },
  ],
  15: [
    { chapter: 15, verse: 1, sanskrit: ["भावाः सर्वे शुभपतियुता वीक्षिता वा शुभेशै-", "स्तत्तद्भावाः सकलफलदाः पापदृग्योगहीनाः ।", "पापाः सर्वे भवनपतयश्चेदिहाहुस्तथैव", "खेटैः सर्वैः शुभफलमिदं नीचमूढारिहीनैः ॥१॥"], gloss: "A house joined or seen by a benefic, its lord or the lords of good houses, and free of malefic aspect or conjunction, gives all its results; a malefic lord of the house does the same; and so do all grahas that are not fallen, combust or in an enemy sign." },
    { chapter: 15, verse: 2, sanskrit: ["तत्तद्भावात् त्रिकोणे स्वसुखमदनभे चास्पदे सौम्ययुक्ते", "पापानां दृष्टिहीने भवनपसहिते पापखेटैरयुक्ते ।", "भावानां पुष्टिमाहुः सकलशुभकरीमन्यथा चेत्प्रणाशं", "मिश्रं मिश्रग्रहेन्द्रैः सकलमपि तथा मूर्तिभावादिकानाम् ॥२॥"], gloss: "A house thrives when its 2nd, trines and kendras have benefics, are free of malefic aspect, and its lord is joined to no malefic; the reverse destroys it; benefics and malefics together give a mixed result." },
    { chapter: 15, verse: 3, sanskrit: ["नाशस्थानगतो दिवाकरकरैर्लुप्तस्तु यद्भावपो", "नीचारातिगृहं गतो यदि भवेत्सौम्यैरयुक्तेक्षितः ।", "तद्भावस्य विनाशनं वितनुते तादृग्विधोऽन्यो ऽस्ति चेत्", "तद्भावोऽपि फलप्रदो न हि शुभश्चेन्नाशमुग्रग्रहः ॥३॥"], gloss: "The lord of a house in the 8th, combust, or in its fall or an enemy's sign, neither joined nor seen by benefics, destroys that house; such a graha destroys the house it stands in too." },
    { chapter: 15, verse: 4, sanskrit: ["लग्नादिभावाद्रिपुरन्ध्ररिःफे पापग्रहास्तद्भवनादिनाशम् ।", "सौम्यास्तु नात्यन्तफलप्रदाः स्युर्भावादिकानां फलमेवमाहुः ॥४॥"], gloss: "Malefics in the 6th, 8th and 12th from a house destroy it; benefics there do not give the full result." },
    { chapter: 15, verse: 5, sanskrit: ["यद्भावनाथो रिपुरन्ध्ररिःफे दुःस्थानपो यद्भवनस्थितो वा ।", "तद्भावनाशं कथयन्ति तज्ज्ञाः शुभेक्षितस्तद्भवनस्य सौख्यम् ॥५॥"], gloss: "The lord of a house in the 6th, 8th or 12th, or the lord of those houses in it, destroys the house; seen by benefics, the house has its common result." },
    { chapter: 15, verse: 6, sanskrit: ["भावाधीशे च भावे सति बलरहिते च ग्रहे कारकाख्ये", "पापान्तःस्थे च पापैररिभिरपि समेतेक्षिते नान्यखेटैः ।", "पापैस्तद्बन्धुमृत्युव्ययभवनगतैस्तत्त्रिकोणस्थितैर्वा", "वाच्या तद्भावहानिः स्फुटमिह भवति द्वित्रिसंवादभावात् ॥६॥"], gloss: "The house, its lord and its significator without strength; between malefics; with malefics or enemies and not with others; malefics in the 4th, 8th, 12th or the trines from it: the house is lost when two or three of these agree." },
    { chapter: 15, verse: 7, sanskrit: ["तत्तद्भावपरा भवेश्वर खरद्रेष्काणपा दुर्बला", "भावार्यष्टमकामगा निजदशायां भावनाशप्रदाः ।", "पापा भावगृहात् त्रिशत्रुभवगाः केन्द्रत्रिकोणे शुभाः", "वीर्याढ्याः खलु भावनाथसुहृदो भावस्य सिद्धिप्रदाः ॥७॥"], gloss: "In their own daśā, the weak lord of the 8th from a house, the lord of its Khara decanate and the grahas in the 6th, 7th and 8th from it destroy it; malefics in the 3rd, 6th and 11th, strong benefics and friends of the lord in kendras and trines make it thrive." },
    { chapter: 15, verse: 8, sanskrit: ["राश्योर्जन्मविलग्नयोर्धृतिपतिर्मृत्युस्थतद्वीक्षकौ", "मन्दः क्रूरदृगाणपो गुलिकपस्तैर्युक्तराश्यंशपाः ।", "राहुश्चैष सुदुर्बलः स जनने … ष्टस्थितः", "पापालोकितसंयुतो निजदशायां भावनाशावहाः ॥८॥"], gloss: "In their own daśā, if very weak and badly placed or afflicted: the lord of the 3rd from the lagna and the Moon sign, the grahas in and seeing the 8th, Saturn, the lord of the cruel decanate, the lord of Gulika and the lords of the sign and navāṁśa they hold, and Rāhu, destroy the houses.", note: "A word of the third line is not legible in the scan." },
    { chapter: 15, verse: 9, sanskrit: ["भावस्योदयपाश्रितस्य कुशलं यद्भावपेनोदय-", "स्वामी तिष्ठति संयुतोऽपि कलयेत्तद्भावजातं फलम् ।", "दुःस्थाने विपरीतमेतदुदितं भावेश्वरे दुर्बले", "दोषोऽतीव भवेद्बलेन सहिते दोषाल्पता जल्पिता ॥९॥"], gloss: "The house where the lagna lord stands thrives, and so do the houses whose lords are joined to him; in an evil house the reverse; a weak house lord brings great fault, a strong one little." },
    { chapter: 15, verse: 10, sanskrit: ["यद्भावेष्वशुभोऽपि वोदयपतिस्तद्भाववृद्धिं दिशे-", "द्दुःस्थानाधिपतिः स चेद्यदि तनोः प्राबल्यमन्यस्य न ।", "अत्रोदाहरणं कुजे सुतगते सिंहे झषे वा स्थिते", "पुत्राप्तिं शुभवीक्षिते झटिति तत्प्राप्तिं वदन्त्युत्तमाः ॥१०॥"], gloss: "The lagna lord, though a malefic, makes the house he stands in thrive, even if he rules an evil house, for the strength of the lagna prevails; Mars in the 5th in Leo or Pisces, seen by benefics: a son soon." },
    { chapter: 15, verse: 11, sanskrit: ["द्विस्थानाधिपतित्वमस्ति यदि चेन्मुख्यं त्रिकोणर्क्षजं", "तस्यार्धं स्वगृहेऽथ पूर्णमुभयोर्यत्तद्दशादौ वदेत् ।", "पश्चाद्भावमिहापरार्धसमये युग्मे गृहे युग्मजं", "त्वोजस्थे सति चौजभावजफलं शंसन्ति केचिज्जनाः ॥११॥"], gloss: "A graha that rules two houses gives the full result of the one in its mūlatrikoṇa sign and half of the other; in its daśā the first part gives one, the second the other; some say, by odd and even signs." },
    { chapter: 15, verse: 12, sanskrit: ["यद्भावेशस्याधिशत्रुग्रहो वा यो वा खेटो बिन्दुशून्यर्क्षयुक्तः ।", "तत्तत्पाके मूर्तिभावादिकानां नाशं ब्रूयाद्दैववित्प्राश्निकाय ॥१२॥"], gloss: "In the daśā of the great enemy of a house lord, or of a graha in a sign without bindus, the astrologer tells the questioner of the loss of the lagna and the other houses." },
    { chapter: 15, verse: 13, sanskrit: ["स्वोच्चे सुहृत्क्षेत्रगतो ग्रहेन्द्रः षड्भिर्बलैर्मुख्यबलान्वितोऽपि ।", "सन्धौ स्थितः सन्नफलप्रदः स्यात् एवं विचिन्त्यात्र वदेद्विपाके ॥१३॥"], gloss: "A graha with the six strengths, in its exaltation or a friend's sign, gives no good result in its daśā if it stands at a junction of houses." },
    { chapter: 15, verse: 14, sanskrit: ["भावेषु भावस्फुटतुल्यभागस्तद्भावजं पूर्णफलं विधत्ते ।", "सन्धौ फलं नास्ति तदन्तराले चिन्त्योऽनुपातः खलु खेचराणाम् ॥१४॥"], gloss: "A graha at the exact point of a house gives its full result; at the junction none; between them in proportion." },
    { chapter: 15, verse: 15, sanskrit: ["सूर्यादात्मपितृप्रभावनिरुजां शक्तिं श्रियं चिन्तयेत्", "चेतोबुद्धिनृपप्रसादजननीसम्पत्करश्चन्द्रमाः ।", "सत्त्वं रोगगुणानुजावनिरिपुज्ञातीन्धरासूनुना", "विद्याबन्धुविवेकमातुलसुहृद्वाक्कर्मकृद्बोधनः ॥१५॥"], gloss: "The Sun for the self, the father, influence, health, strength and fortune; the Moon for the mind, intellect, the king's favour, the mother and wealth; Mars for courage, disease, brothers, land, enemies and kin; Mercury for learning, relatives, discernment, the maternal uncle, friends and speech." },
    { chapter: 15, verse: 16, sanskrit: ["प्रज्ञावित्तशरीरपुष्टितनयज्ञानानि वागीश्वरात्", "पत्नीवाहनभूषणानि मदनव्यापारसौख्यं भृगोः ।", "आयुर्जीवनमृत्युकारणविपद्भृत्यांश्च मन्दाद्वदेत्", "सर्पेणैव पितामहं तु शिखिना मातामहं चिन्तयेत् ॥१६॥"], gloss: "Jupiter for intelligence, wealth, the body, children and knowledge; Venus for the wife, vehicles, ornaments, desire and pleasure; Saturn for life, death, calamity and servants; Rāhu for the father's father and Ketu for the mother's father." },
    { chapter: 15, verse: 17, sanskrit: ["द्युमणिरमरमन्त्री भूसुतः सोमसौम्यौ", "गुरुरिनतनयारौ भार्गवो भानुपुत्रः ।", "दिनकरदिविजेज्यौ जीवभानुज्ञमन्दाः", "सुरगुरुरिनसूनुः कारकाः स्युर्विलग्नात् ॥१७॥"], gloss: "The significators of the houses from the lagna: the Sun, Jupiter, Mars, Mercury and the Moon, Jupiter, Saturn and Mars, Venus, Saturn, the Sun and Jupiter, Jupiter, the Sun, Mercury and Saturn, Jupiter, Saturn." },
    { chapter: 15, verse: 18, sanskrit: ["सुहृदरिपरकीयस्वर्क्षतुङ्गस्थितानां", "फलमनुपरिचिन्त्यं लग्नदेहादिभावैः ।", "समुपचयविपत्ती सौम्यपापेषु सत्यः", "कथयति विपरीतं रिःफषष्ठाष्टमेषु ॥१८॥"], gloss: "The result of the grahas in the houses is read by their being in a friend's, an enemy's, a neutral's, their own or their exalted sign: growth or loss; Satya says benefics make growth and malefics loss, the reverse in the 12th, 6th and 8th." },
    { chapter: 15, verse: 19, sanskrit: ["पापग्रहाः षष्ठमृतिव्ययस्थास्तद्भाववृद्धिं कलयन्ति दोषैः ।", "शुभास्तु तद्भावलयं हि तस्माच्छ … भावात्फलप्रणाशः ॥१९॥"], gloss: "Malefics in the 6th, 8th and 12th make their house thrive by removing its faults; benefics there dissolve the house and its results.", note: "A word of the second line is not legible in the scan." },
    { chapter: 15, verse: 20, sanskrit: ["भावस्य यस्यैव फलं विचिन्त्यं भावं च तं लग्नमिति प्रकल्प्य ।", "तस्माद्वदेद्द्वादशभावजानि फलानि तद्रूपधनादिकानि ॥२०॥"], gloss: "For the house whose result is sought, take that house as the lagna and read the twelve houses from it for its body, wealth and the rest." },
    { chapter: 15, verse: 21, sanskrit: ["एवं हि तत्कारकतो विचिन्त्यं पितुश्च मातुश्च सहोदरस्य ।", "तन्मातुलस्यापि सुतस्य पत्युर्भृत्यस्य सूर्यादिखगस्थितर्क्षात् ॥२१॥"], gloss: "The father, mother, brother, maternal uncle, son, husband and servant are read from the sign of their significators, the Sun and the rest." },
    { chapter: 15, verse: 22, sanskrit: ["सूर्यस्थितर्क्षाज्जनकस्वरूपं वृद्धिं द्वितीयेन तु तत्प्रकाशम् ।", "तद्भ्रातरं तस्य गुणं तृतीयात्तन्मातरं चापि सुखं चतुर्थात् ॥२२॥"], gloss: "From the sign of the Sun: the form of the father; from the 2nd his growth and fame; the 3rd his brother and virtue; the 4th his mother and happiness." },
    { chapter: 15, verse: 23, sanskrit: ["बुद्धिं प्रसादं सुतभाच्च षष्ठात् पीडां पितुर्दोषमरिं च रोगम् ।", "कामं मदं तस्य तु सप्तमेन दुःखं मृतिं मृत्युगृहात्तदायुः ॥२३॥"], gloss: "From the 5th his intellect and favour; the 6th his troubles, faults, enemies and disease; the 7th his desire and pride; the 8th his sorrow, death and span of life." },
    { chapter: 15, verse: 24, sanskrit: ["पुण्यं शुभं तत्पितरं शुभेन व्यापारमस्यैव हि कर्मभावात् ।", "लाभं ह्युपान्त्यात् क्षयमन्त्यभावाच्चन्द्रादिकानां फलमेवमाहुः ॥२४॥"], gloss: "From the 9th his merit and good; the 10th his business; the 11th his gains; the 12th his loss; the Moon and the rest are read the same way." },
    { chapter: 15, verse: 25, sanskrit: ["तत्तद्भावात्कारकादेवमूहां तत्तन्मातृभ्रातृपित्रात्मजाद्यम् ।", "तस्मिन् भावे कारके भावनाथे वीर्योपेते तस्य भावस्य सौख्यम् ॥२५॥"], gloss: "The mother, brother, father, son and the rest are read from their houses and significators; when the house, the significator and the lord are strong, that house is happy." },
    { chapter: 15, verse: 26, sanskrit: ["धर्मे सूर्यः शीतगुर्बन्धुभावे शौर्ये भौमः पञ्चमे देवमन्त्री ।", "कामे शुक्रश्चाष्टमे भानुपुत्रः … क्लेशमित्याहुरन्ये ॥२६॥"], gloss: "Others say the Sun in the 9th, the Moon in the 4th, Mars in the 3rd, Jupiter in the 5th, Venus in the 7th and Saturn in the 8th bring trouble to the house.", note: "A word of the second line is not legible in the scan." },
    { chapter: 15, verse: 27, sanskrit: ["लग्नेश्वरो यद्भवनेशयुक्तो यद्भावगस्तस्य फलं ददाति ।", "भावे तदीशे बलभाजि तेन भावेन सौख्यं व्यसनं …॥२७॥"], gloss: "The lagna lord gives the result of the house whose lord he is with and of the house he stands in; when that house and its lord are strong, happiness; otherwise trouble.", note: "The end of the second line is not legible in the scan." },
    { chapter: 15, verse: 28, sanskrit: ["यद्भावप्रभुणा युतो बलवता मुख्याङ्गगो लग्नप-", "स्तद्भावानुभवं वितनुते यद्भावगस्तस्य च ।", "संयुक्तो बलहीनभावपतिना निन्द्याङ्गभाजां फलं", "कुर्यात्तद्विपरीतमेवमुदितं सर्वेषु भावेष्वपि ॥२८॥"], gloss: "The lagna lord with a strong house lord, in a good part of his own aṣṭakavarga, gives the experience of that house; with a weak lord, in a poor part, the reverse; so for all houses." },
    { chapter: 15, verse: 29, sanskrit: ["दुःस्थानपस्तदितरस्वगृहस्थितश्चेत्", "स्वेक्षेत्रभावफलमेव करोति नान्यत् ।", "मन्दो मृगे सुतगृहे यदि पुत्रसिद्धिः", "षष्ठाधिपत्यकृतदोषफलं च नात्र ॥२९॥"], gloss: "The lord of an evil house standing in his own other house gives only the result of that house: Saturn in Capricorn, lord of the 5th and 6th, in the 5th gives sons, without the fault of the 6th." },
    { chapter: 15, verse: 30, sanskrit: ["राशौ स्थितिर्मिथो योगो दृष्टिः केन्द्रेषु संस्थितिः ।", "त्रिकोणे वा स्थितिः पञ्चप्रकारो बन्ध ईरितः ॥३०॥"], gloss: "The five kinds of connection: standing in each other's sign, joining, aspect, standing in kendras from each other, standing in trines from each other." },
  ],
  16: [
    { chapter: 16, verse: 1, sanskrit: ["लग्ननवांशपतुल्यतनुः स्याद्वीर्ययुतग्रहतुल्यतनुर्वा ।", "चन्द्रसमेतनवांशपवर्णः कादिविलग्नविभक्तभगात्रः ॥१॥"], gloss: "The body is like the lord of the lagna navāṁśa or the strongest graha; the complexion is that of the lord of the Moon's navāṁśa; the limbs come from the signs on the parts of Kālapuruṣa.", note: "A word of the second line is doubtful in the scan." },
    { chapter: 16, verse: 2, sanskrit: ["लग्नेशे केन्द्रकोणे स्फुटकरनिकरे स्वोच्चभे वा स्वभे वा", "केन्द्रादन्यत्र संस्थे निधनभवनपे सौम्ययुक्ते विलग्ने ।", "दीर्घायुष्मान्धनाढ्यो महितगुणयुतो भूमिपालप्रशस्तो", "लक्ष्मीवान् सुन्दराङ्गो दृढतनुरभयो धार्मिकः सत्कुटुम्बी ॥२॥"], gloss: "The lagna lord in a kendra or trine, not combust, in its exaltation or own sign, the 8th lord with benefics away from the kendras and the lagna with a benefic: long-lived, rich, praised by kings, fortunate, handsome, strong, fearless, righteous, with a good family." },
    { chapter: 16, verse: 3, sanskrit: ["सत्सम्बन्धयुते कलेवरपतौ सद्ग्रामवासोऽथवा", "सत्सङ्गः प्रबलग्रहेण सहिते विख्यातभूपाश्रयः ।", "स्वोच्चस्थे नृपतिः स्वयं स्वगृहगे तज्जन्मभूमौ स्थितिः", "सञ्चारश्चरभे स्थितिः स्थिरगृहे … द्विरूपं फलम् ॥३॥"], gloss: "The lagna lord with benefics: a home in a good village; with a strong graha: famous with a king's protection; exalted: a king; in its own sign: he stays in his birthplace; in a movable sign he roams, in a fixed one he stays, in a dual one both.", note: "A word of the last line is not legible in the scan." },
    { chapter: 16, verse: 4, sanskrit: ["विख्यातः किरणोज्ज्वले तनुपतौ सुस्थे सुखी वर्धनो", "दुःस्थे दुःख्यसदृक्षनीचभवने वासो निकृष्टस्थले ।", "स्वस्थो जीवति शक्तिमत्युदयभे वर्द्धिष्णुरूर्जस्वलो", "निःशक्तौ निहतो विपद्भिरसकृत्खिन्नो भवेदातुरः ॥४॥"], gloss: "The lagna lord bright and well placed: famous, happy and growing; in an evil house or in a sign unlike his own or his fall: unhappy, living in a low place; a strong lagna: healthy and thriving; a weak lagna: struck by calamities, weary and ill." },
    { chapter: 16, verse: 5, sanskrit: ["अर्थस्वामिनि मुख्यभावजुषि सत्स्वर्थे कुटुम्बश्रिया", "सर्वोत्कृष्टगुणो धनी च सुमुखी स्याद्दूरदर्शी नरः ।", "सम्बन्धे सवितुर्द्वितीयपतिना लोकोपकारक्षमां", "विद्यामर्थमवाप्नुयादथ शनेः क्षुद्राल्पविद्यारतः ॥५॥"], gloss: "The 2nd lord in the lagna with benefics: a family of fortune, the best qualities, wealth, a pleasant face and foresight; the lagna lord strong in the 2nd also gives wealth; the 2nd lord with the Sun: learning and wealth that serve the world; with Saturn: fond of petty and little learning." },
    { chapter: 16, verse: 6, sanskrit: ["जैवे वैदिकधर्मशास्त्रनिपुणो बौधेऽर्थशास्त्रे पटुः", "शृङ्गारोक्तिपटुर्भृगोर्हिमरुचेः किञ्चित्कलाविद्भवेत् ।", "कौजे क्रूरकलापटुश्च पिशुनो राहौ स्थिते लोहलः", "केतौ भ्रश्यदलीकवाग्धनगतैः पापैश्च मूढोऽधनः ॥६॥"], gloss: "The 2nd lord with Jupiter: skilled in the Veda and the law; Mercury: in the science of wealth; Venus: in amorous speech; the Moon: some skill in the arts; Mars: cruel and a slanderer; Rāhu there: a stammerer; Ketu: halting and false speech; malefics in the 2nd: a fool without wealth." },
    { chapter: 16, verse: 7, sanskrit: ["बन्धो यदि स्यात्तनुशौर्यनाथयोरन्योन्यराशिस्थितयोर्बलाढ्ययोः ।", "धैर्यं च शौर्यं सहजानुकूलतां प्राप्नोत्ययं साहसकार्यकर्तृताम् ॥७॥"], gloss: "The lords of the lagna and the 3rd, strong and in each other's signs: steadfast, brave, kind to his brothers and able in daring deeds." },
    { chapter: 16, verse: 8, sanskrit: ["शौर्यपे बलिनि सद्ग्रहयुक्ते कारकेऽपि शुभभावमुपेते ।", "भ्रातृवृद्धिरथ वीर्यविहीने दुःस्थिति भवति सोदरनाशः ॥८॥"], gloss: "The 3rd lord strong and with benefics, and the significator in a good house: his brothers grow; both weak and badly placed: the brothers are lost." },
    { chapter: 16, verse: 9, sanskrit: ["अयुग्मराशौ यदि कारकेशौ गुर्वर्कभूसूनुनिरीक्षितौ चेत् ।", "ओजो गृहः स्याद्यदि विक्रमाख्यः पुंभ्रातरस्त्वंशवशाद्भवेयुः ॥९॥"], gloss: "The significator and the 3rd lord in an odd sign, seen by Jupiter, the Sun and Mars, the 3rd house itself odd: the brothers are men, by the navāṁśa." },
    { chapter: 16, verse: 10, sanskrit: ["दुःस्थाने सुखपे शशिन्यपि सतां योगेक्षणैर्वर्जिते", "पापान्तः स्थितिमत्यसद्ग्रहयुते दृष्टे जनन्या मृतिः ।", "एतौ द्वावपि वीर्यगौ शुभयुतौ दृष्टौ शुभैर्बन्धुगै-", "र्मातुः सौख्यकरौ विधोश्च सुखगैः सौम्यैर्वदेत्तत्सुखम् ॥१०॥"], gloss: "The 4th lord and the Moon in evil houses, without benefic aspect or conjunction, between malefics or with malefics: the mother's death; both strong, with benefics and seen by them, benefics in the 4th: the mother's happiness; benefics in the 4th from the Moon likewise." },
    { chapter: 16, verse: 11, sanskrit: ["लग्नेशे सुखगेऽथवा सुखपतौ लग्ने तयोरीक्षणे", "योगे वा शशिनस्तथा यदि करोत्यन्त्यां स्वमातुः क्रियाम् ।", "अन्योन्यं यदि शत्रुनीचभवने षष्ठाष्टमे वा तयो-", "र्मातुर्नोपकरोति नाशसमये बन्धस्तयोर्वा न चेत् ॥११॥"], gloss: "The lagna lord in the 4th or the 4th lord in the lagna, seen or joined by the Moon: he does his mother's last rites; the two in each other's enemy or fallen sign, or in the 6th and 8th, and not connected: he is no help to her at her death." },
    { chapter: 16, verse: 12, sanskrit: ["मातृभावोक्तवद्वाच्यं पितृभ्रातृसुतादिषु ।", "भावकारकभावेशलग्नलग्नेश्वरैर्वदेत् ॥१२॥"], gloss: "What is told of the mother's house is told of the father, brothers, sons and the rest, by the house, its significator and lord, the lagna and its lord." },
    { chapter: 16, verse: 13, sanskrit: ["… सुखेशभृगुजौ तनुबन्धुयुक्तौ", "आन्दोलिकां जनपतेश्वरतां विधत्तः ।", "स्वर्णाद्यनर्घ्यमणिभूषणपट्टशय्या-", "कामोपभोगकरणानि च गोगजाश्वान् ॥१३॥"], gloss: "The 4th lord in the lagna and Venus in the 4th, in comfort (or both in good houses): a palanquin, lordship over men, gold, priceless jewels, ornaments, silk, beds, cattle, elephants and horses.", note: "The first word is lost in the scan." },
    { chapter: 16, verse: 14, sanskrit: ["दुःस्थे सुखेशे कुजसूर्ययुक्ते सुखेऽपि वा जन्मगृहं प्रदग्धम् ।", "जीर्णं तमोमन्दयुतेऽरियुक्ते परैर्हृतं गोक्षितिवाहनाद्यम् ॥१४॥"], gloss: "The 4th lord in an evil house with Mars and the Sun, or the 4th so joined: the birthplace burns; with Rāhu and Saturn: it is decayed; with an enemy: cattle, land and vehicles are taken by others." },
    { chapter: 16, verse: 15, sanskrit: ["सौम्यर्क्षांशे सौम्ययुक्ते पञ्चमे वा तदीश्वरे ।", "वैशेषिकांशे सद्भावे धीमान्निष्कपटी भवेत् ॥१५॥"], gloss: "The 5th a sign and navāṁśa of Mercury, Mercury in it, or the 5th lord in a special division in a good house: intelligent and sincere." },
    { chapter: 16, verse: 16, sanskrit: ["स्थितिः पापानां वा द्विषति बलयुक्तारिपतिना", "युतो वा दृष्टो वा यदि रिपुगृहे वा तनुपतिः ।", "अरीशः केन्द्रे वाप्यशुभखगसंवीक्षितयुतो", "रिपूणां पीडां द्राग्भृशमपरिहार्यां वितनुते ॥१६॥"], gloss: "Malefics in the 6th; or the lagna lord joined or seen by a strong 6th lord; or in the 6th; or the 6th lord in a kendra joined or seen by malefics: the trouble from enemies is quick, great and not to be turned." },
    { chapter: 16, verse: 17, sanskrit: ["षष्ठेश्वरादतिबलिन्युदयाधिनाथे", "सौम्यग्रहांशसहिते शुभदृष्टियुक्ते ।", "सौख्येश्वरेऽपि सबले यदि केन्द्रकोणे-", "ष्वारोग्यभाग्यसहितो दृढगात्रयुक्तः ॥१७॥"], gloss: "The lagna lord stronger than the 6th lord, in a benefic navāṁśa and seen by benefics, the 4th lord strong in a kendra or trine: healthy, fortunate and strong of body." },
    { chapter: 16, verse: 18, sanskrit: ["शत्रुनाथे तु दुःस्थाने नीचमूढारिसंयुते ।", "तस्माद्बलाढ्ये लग्नेशे शत्रुनाशं रवौ शुभे ॥१८॥"], gloss: "The 6th lord in an evil house, fallen, combust or with an enemy, the lagna lord stronger, and the Sun well placed (in the 9th): the enemies are destroyed." },
    { chapter: 16, verse: 19, sanskrit: ["यद्भावेशयुतो वैरिनाथो यद्भावसंश्रितः ।", "षष्ठस्थितो यद्भावेशस्ते भावाः शत्रुतां ययुः ॥१९॥"], gloss: "The houses whose lord the 6th lord is joined to, the house the 6th lord stands in, and the houses whose lord stands in the 6th, become enemies." },
    { chapter: 16, verse: 20, sanskrit: ["सत्सम्बन्धयुते सप्तर्क्षे तदीशे बलान्विते ।", "पतिपुत्रवती साध्वी भार्या सर्वगुणैर्वृता ॥२०॥"], gloss: "The 7th joined to a benefic and its lord strong: a wife who is good, with a husband and sons, rich in every virtue." },
    { chapter: 16, verse: 21, sanskrit: ["केन्द्रादन्यत्र रन्ध्रेशे लग्नेशाद्दुर्बले सति ।", "नाधिर्न विघ्नो न क्लेशो नृणामायुश्चिरं भवेत् ॥२१॥"], gloss: "The 8th lord weaker than the lagna lord and away from the kendras: no illness, no obstacle, no suffering, a long life." },
    { chapter: 16, verse: 22, sanskrit: ["धर्मे कुजे वा सूर्ये वा दुःस्थे तन्नायके सति ।", "पापमध्यगते वापि पितुर्मरणमादिशेत् ॥२२॥"], gloss: "The 9th with Mars or the Sun and its lord in an evil house, or between malefics: the father's death." },
    { chapter: 16, verse: 23, sanskrit: ["दिवा सूर्ये निशा मन्दे सुस्थे शुभनिरीक्षिते ।", "धर्मेशे बलसंयुक्ते चिरं जीवति तत्पिता ॥२३॥"], gloss: "The Sun by day or Saturn by night well placed and seen by benefics, the 9th lord strong: the father lives long." },
    { chapter: 16, verse: 24, sanskrit: ["मन्दारयोः शीतरुचौ च सूर्ये त्रिकोणगे तज्जननीपितृभ्याम् ।", "त्यक्तो भवेच्छक्रपुरोहितेन दृष्टे तनूजोऽस्ति सुखी चिरायुः ॥२४॥"], gloss: "Saturn and Mars, with the Moon and the Sun in the trines: he is left by his mother and father; seen by Jupiter, the son is happy and long-lived." },
    { chapter: 16, verse: 25, sanskrit: ["शनिर्भाग्याधिपः स्याच्चेच्चरस्थो न शुभेक्षितः ।", "सूर्ये दुःस्थानगेऽप्यन्यपितरं ह्युपजीवति ॥२५॥"], gloss: "Saturn the lord of the 9th in a movable sign unseen by benefics and the Sun in an evil house: he lives on another's father." },
    { chapter: 16, verse: 26, sanskrit: ["धर्मे तदीशे वा मन्दयुक्ते दृष्टेऽपि वा चरे ।", "जातो दत्तो भवेन्नूनं व्ययेशे बलशालिनि ॥२६॥"], gloss: "The 9th or its lord joined or seen by Saturn in a movable sign, the 12th lord strong: he is surely given in adoption." },
    { chapter: 16, verse: 27, sanskrit: ["नभसि शुभखगे वा तत्पतौ केन्द्रकोणे", "बलिनि निजगृहोच्चे कर्मगे लग्नपे वा ।", "महितपृथुयशाः स्याद्धर्मकर्मप्रवृत्ति-", "र्नृपतिसदृशभाग्यं दीर्घमायुश्च तस्य ॥२७॥"], gloss: "A benefic in the 10th, and its lord strong in a kendra or trine in its own sign or exaltation, or the lagna lord in the 10th: great fame, a righteous life, a king's fortune and long life." },
    { chapter: 16, verse: 28, sanskrit: ["ऊर्जस्वी जनवल्लभो दशमगे सूर्ये कुजे वा महत्", "कार्यं साधयति प्रतापबहुलं खेशश्च सुस्थो यदि ।", "सद्व्यापारवतीं क्रियां वितनुते सौम्येषु सच्छ्लाघितां", "कर्मस्थेष्वहिमन्दकेतुषु भवेद्दुष्कर्मकारी नरः ॥२८॥"], gloss: "The Sun or Mars in the 10th: full of energy and loved; the 10th lord well placed: he does great deeds by his own prowess; benefics in the 10th: worthy work praised by the good; Rāhu, Saturn or Ketu in the 10th: an evil-doer." },
    { chapter: 16, verse: 29, sanskrit: ["लाभेशे यद्भावनाथयुक्ते यद्भावगेऽपि वा ।", "भावं तदनुरूपस्य वस्तुनो लाभगैरपि ॥२९॥"], gloss: "Gain of the things of a house: the 11th lord joined to its lord, or in it, or its lord in the 11th." },
    { chapter: 16, verse: 30, sanskrit: ["व्ययस्थितो यद्भावेशो व्ययेशो यत्र तिष्ठति ।", "तस्य भावस्यानुरूपवस्तुनो नाशमादिशेत् ॥३०॥"], gloss: "Loss of the things of a house: its lord in the 12th, or the 12th lord in it." },
    { chapter: 16, verse: 31, sanskrit: ["भावेशस्थितभांशकोणमपि वा भावं तु वा लग्नपो", "लग्नेशस्थितभांशकोणमुदयं वाऽऽयाति भावाधिपः ।", "संयोगेऽपि विलोकनेऽपि च तयोस्तद्भावसिद्धिं तदा", "ब्रूयात्कारकयोगतस्तनुपतेर्लग्नाच्च चन्द्रादपि ॥३१॥"], gloss: "The time a house bears fruit: the lagna lord comes by transit to the navāṁśa sign or trine of the house lord, or the house lord to those of the lagna lord, in conjunction or aspect, with the significator, from the lagna and from the Moon." },
    { chapter: 16, verse: 32, sanskrit: ["यद्भावेशस्थितर्क्षांशत्रिकोणस्थे गुरुर्यदा ।", "गोचरे तस्य भावस्य फलप्राप्तिं विनिर्दिशेत् ॥३२॥"], gloss: "When Jupiter by transit is in the trine of the sign or navāṁśa where the lord of a house stands, the result of that house is gained." },
    { chapter: 16, verse: 33, sanskrit: ["लग्नारिनाथयोगे तु लग्नेशाद्दुर्बले रिपौ ।", "तदा तद्वशगः शत्रुर्विपरीतमतोऽन्यथा ॥३३॥"], gloss: "When the lagna lord and the 6th lord join and the 6th lord is weaker than the lagna lord, the enemy comes under his power; the reverse otherwise." },
    { chapter: 16, verse: 34, sanskrit: ["यद्भावपस्य तनुपस्य भवत्यरित्वात्", "तत्कालशत्रुवशतोऽरिमृतिस्थितो वा ।", "स्पर्धां तदा वदतु तेन च गोचरस्थ-", "स्तद्वत्सुहृत्त्वमपि संयुतिमैत्रतश्च ॥३४॥"], gloss: "By the enmity between the lagna lord and a house lord, or the lord in the 6th or 8th, he tells of rivalry in the time of the transit; and likewise of friendship by the friendly junction." },
    { chapter: 16, verse: 35, sanskrit: ["लग्नेशयद्भावपयोस्तु योगो यदा तदा तत्फलसिद्धिकालः ।", "भावेशवीर्ये शुभमन्यथान्यल्लग्नाच्च चन्द्रादपि चिन्तनीयम् ॥३५॥"], gloss: "When the lagna lord and the house lord join, that is the time the result is gained: good if the house lord is strong, otherwise not; from the lagna and from the Moon." },
  ],
};
